import { Hono } from 'hono';
import type { Config } from './config';

export type AppDeps = { config: Config };

export type AppEnv = { Variables: { config: Config } };

// The factory receives its dependencies, so tests build the app without starting a server.
export const createApp = (deps: AppDeps): Hono<AppEnv> => {
  const app = new Hono<AppEnv>();

  // Routes read configuration from the request context, never from process.env (T7).
  app.use(async (c, next) => {
    c.set('config', deps.config);
    await next();
  });

  app.get('/api/health', (c) => c.json({ status: 'ok' }));

  // One handler for every unhandled error. The client gets a fixed body with no stack trace.
  // Only the error name is logged, because the message may contain document text (T10).
  app.onError((error, c) => {
    const line = { level: 'error', event: 'unhandled', name: error.name };
    process.stdout.write(`${JSON.stringify(line)}\n`);
    return c.json({ error: 'internal' }, 500);
  });

  return app;
};

