import { useCallback, useEffect, useState } from 'react';
import {
  useDocumentStore,
  type DocumentSummary,
  type Result,
  type StoreError,
} from '@/features/documents';

export type DocumentListState =
  { kind: 'loading' } | { kind: 'error' } | { kind: 'ready'; documents: DocumentSummary[] };

export interface UseDocumentsResult {
  state: DocumentListState;
  // Re-runs the read after an error (D14). Same function as reload, which later phases call after
  // a mutation such as delete (H5).
  retry: () => void;
  reload: () => void;
}

function toListState(result: Result<DocumentSummary[], StoreError>): DocumentListState {
  if (result.ok) {
    return { kind: 'ready', documents: result.value };
  }
  return { kind: 'error' };
}

// H1: reads the document index only. A failed read becomes the error state, never a blank screen (D14).
export function useDocuments(): UseDocumentsResult {
  const store = useDocumentStore();
  const [state, setState] = useState<DocumentListState>({ kind: 'loading' });
  const [readCount, setReadCount] = useState(0);

  useEffect(() => {
    let active = true;
    store.list().then(
      (result) => {
        if (active) {
          setState(toListState(result));
        }
      },
      () => {
        if (active) {
          setState({ kind: 'error' });
        }
      },
    );
    return () => {
      active = false;
    };
  }, [store, readCount]);

  const reload = useCallback((): void => {
    setState({ kind: 'loading' });
    setReadCount((count) => count + 1);
  }, []);

  return { state, retry: reload, reload };
}
      {options.view === 'grid' ? (
        <DocumentGrid documents={state.documents} now={options.now} />
      ) : (
        <DocumentList documents={state.documents} now={options.now} />
      )}
    </>
  );
}

// H1-H4, H6: the app's first screen. Every read state is rendered; none blanks the page (D14).
export function HomePage({ newId = createDocumentId, now }: HomePageProps): JSX.Element {
  const navigate = useNavigate();
  const { state, retry } = useDocuments();
  const [view, setView] = useState<DocumentView>('grid');
  const renderedAt = now ?? Date.now();

  function startNewDocument(): void {
    void navigate(`/documents/${newId()}`);
  }

  return (
    <AppShell navbar={<HomeNavbar />} sidebar={<HomeSidebar onNewDocument={startNewDocument} />}>
      <div className="home-page">
        <h1 className="home-page__title">Documents</h1>
        {renderDocuments(state, {
          view,
          now: renderedAt,
          onViewChange: setView,
          onRetry: retry,
          onNewDocument: startNewDocument,
        })}
      </div>
    </AppShell>
  );
}

