import { fireEvent, render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { createMemoryRouter, RouterProvider } from 'react-router';
import { describe, expect, it } from 'vitest';
import {
  DocumentStoreProvider,
  type DocumentStore,
  type DocumentSummary,
} from '@/features/documents';
import { HomePage } from './HomePage';
import { deferred, deletableStore } from './testStore';

const PLAN: DocumentSummary = { id: 'doc-plan', title: 'Plan', preview: 'Goals', updatedAt: 0 };
const NOTES: DocumentSummary = { id: 'doc-notes', title: 'Notes', preview: '', updatedAt: 0 };
const DELETE_FAILED = 'Could not delete this document. It is still saved. Try again.';

const SUCCESS = (): Promise<{ ok: true; value: undefined }> =>
  Promise.resolve({ ok: true, value: undefined });

function renderHome(store: DocumentStore): void {
  const router = createMemoryRouter(
    [
      { path: '/', element: <HomePage newId={() => 'unused'} /> },
      { path: '/documents/:id', element: <p>Editor</p> },
    ],
    { initialEntries: ['/'] },
  );
  render(
    <DocumentStoreProvider store={store}>
      <RouterProvider router={router} />
    </DocumentStoreProvider>,
  );
}

// The dialog stays in the DOM when closed; its open attribute is the state the user sees.
function dialogIsOpen(): boolean {
  return document.querySelector('dialog')?.hasAttribute('open') === true;
}

function documentsHeading(): HTMLElement {
  return screen.getByRole('heading', { level: 1, name: 'Documents' });
}

// H5: the delete flow, from the trash button to the refreshed list.
describe('HomePage delete flow (H5, D14)', () => {
  // H5: the delete button opens a confirmation that names the document.
  it('opens a confirmation naming the document from its delete button (H5)', async () => {
    const user = userEvent.setup();
    const { store } = deletableStore([PLAN], SUCCESS);
    renderHome(store);

    await screen.findByRole('link', { name: 'Plan' });
    await user.click(screen.getByRole('button', { name: 'Delete "Plan"' }));

    expect(dialogIsOpen()).toBe(true);
    expect(screen.getByText('Delete "Plan"?')).toBeTruthy();
    expect(screen.getByText(/This can't be undone\./)).toBeTruthy();
  });

  // H5: Cancel closes the dialog, keeps the document, and returns focus to its delete button.
  it('Cancel closes the confirmation, keeps the document and returns focus to its trigger (H5)', async () => {
    const user = userEvent.setup();
    const { store, removed } = deletableStore([PLAN], SUCCESS);
    renderHome(store);

    await screen.findByRole('link', { name: 'Plan' });
    const trigger = screen.getByRole('button', { name: 'Delete "Plan"' });
    await user.click(trigger);
    await user.click(screen.getByRole('button', { name: 'Cancel' }));

    expect(dialogIsOpen()).toBe(false);
    expect(removed).toEqual([]);
    expect(screen.getByRole('link', { name: 'Plan' })).toBeTruthy();
    expect(document.activeElement).toBe(trigger);
  });

  // H5: confirm removes the document; while the reload is pending the list stays visible and no
  // spinner appears (stale-while-revalidate). The gate is released to let the refresh finish.
  it('refreshes the list in place with no spinner while the reload is pending (H5)', async () => {
    const user = userEvent.setup();
    const base = deletableStore([PLAN, NOTES], SUCCESS);
    const gate = deferred<undefined>();
    let reads = 0;
    const store: DocumentStore = {
      ...base.store,
      list: () => {
        reads += 1;
        return reads === 1 ? base.store.list() : gate.promise.then(() => base.store.list());
      },
    };
    renderHome(store);

    await screen.findByRole('link', { name: 'Plan' });
    await user.click(screen.getByRole('button', { name: 'Delete "Plan"' }));
    await user.click(screen.getByRole('button', { name: 'Delete document' }));

    await waitFor(() => {
      expect(dialogIsOpen()).toBe(false);
    });
    expect(screen.queryByRole('status')).toBeNull();
    expect(screen.getByRole('link', { name: 'Plan' })).toBeTruthy();

    gate.resolve(undefined);

    await waitFor(() => {
      expect(screen.queryByRole('link', { name: 'Plan' })).toBeNull();
    });
    expect(screen.getByRole('link', { name: 'Notes' })).toBeTruthy();
    expect(screen.queryByRole('status')).toBeNull();
    expect(base.removed).toEqual(['doc-plan']);
  });

  // H5: after a successful delete, focus moves to the Documents heading, since the removed
  // card's button can no longer hold it.
  it('moves focus to the Documents heading after a successful delete (H5, S7)', async () => {
    const user = userEvent.setup();
    const { store } = deletableStore([PLAN, NOTES], SUCCESS);
    renderHome(store);

    await screen.findByRole('link', { name: 'Plan' });
    await user.click(screen.getByRole('button', { name: 'Delete "Plan"' }));
    await user.click(screen.getByRole('button', { name: 'Delete document' }));

    await waitFor(() => {
      expect(dialogIsOpen()).toBe(false);
    });
    expect(document.activeElement).toBe(documentsHeading());
  });

  // D14, H5: not-found means the document is already gone, so the list simply drops it.
  it('treats a not-found result as deleted and drops the document (D14, H5)', async () => {
    const user = userEvent.setup();
    const { store } = deletableStore([PLAN], () =>
      Promise.resolve({ ok: false, error: { kind: 'not-found' } }),
    );
    renderHome(store);

    await screen.findByRole('link', { name: 'Plan' });
    await user.click(screen.getByRole('button', { name: 'Delete "Plan"' }));
    await user.click(screen.getByRole('button', { name: 'Delete document' }));

    await waitFor(() => {
      expect(screen.queryByRole('link', { name: 'Plan' })).toBeNull();
    });
    expect(dialogIsOpen()).toBe(false);
  });

  // D14: a failed delete keeps the dialog open with the error and the document still listed.
  it('keeps the dialog open with an error when the store fails, and the document listed (D14)', async () => {
    const user = userEvent.setup();
    const { store } = deletableStore([PLAN], () =>
      Promise.resolve({ ok: false, error: { kind: 'quota' } }),
    );
    renderHome(store);

    await screen.findByRole('link', { name: 'Plan' });
    await user.click(screen.getByRole('button', { name: 'Delete "Plan"' }));
    await user.click(screen.getByRole('button', { name: 'Delete document' }));

    expect(await screen.findByText(DELETE_FAILED)).toBeTruthy();
    expect(dialogIsOpen()).toBe(true);
    expect(screen.getByRole('link', { name: 'Plan' })).toBeTruthy();
  });

  // D14: a rejected delete (storage disabled) is shown the same way, never thrown or lost.
  it('keeps the dialog open with an error when the store rejects (D14)', async () => {
    const user = userEvent.setup();
    const { store } = deletableStore([PLAN], () => Promise.reject(new Error('storage disabled')));
    renderHome(store);

    await screen.findByRole('link', { name: 'Plan' });
    await user.click(screen.getByRole('button', { name: 'Delete "Plan"' }));
    await user.click(screen.getByRole('button', { name: 'Delete document' }));

    expect(await screen.findByText(DELETE_FAILED)).toBeTruthy();
    expect(dialogIsOpen()).toBe(true);
    expect(screen.getByRole('link', { name: 'Plan' })).toBeTruthy();
  });

  // D14: if the list cannot be re-read after a successful delete, the error state is shown.
  // This documents the current behavior: a failed silent reload replaces the list with the error.
  it('shows the load error when the reload fails after a successful delete (D14)', async () => {
    const user = userEvent.setup();
    const base = deletableStore([PLAN, NOTES], SUCCESS);
    let reads = 0;
    const store: DocumentStore = {
      ...base.store,
      list: () => {
        reads += 1;
        return reads === 1
          ? base.store.list()
          : Promise.resolve({ ok: false, error: { kind: 'corrupt' } } as const);
      },
    };
    renderHome(store);

    await screen.findByRole('link', { name: 'Plan' });
    await user.click(screen.getByRole('button', { name: 'Delete "Plan"' }));
    await user.click(screen.getByRole('button', { name: 'Delete document' }));

    await screen.findByRole('heading', { level: 2, name: 'Could not load your documents' });
    expect(dialogIsOpen()).toBe(false);
    expect(screen.queryByRole('link', { name: 'Plan' })).toBeNull();
  });

  // S7, D14: Esc closes the confirmation when nothing is running and leaves the list alone.
  it('Esc cancels the confirmation when not busy (H5, S7)', async () => {
    const user = userEvent.setup();
    const { store, removed } = deletableStore([PLAN], SUCCESS);
    renderHome(store);

    await screen.findByRole('link', { name: 'Plan' });
    await user.click(screen.getByRole('button', { name: 'Delete "Plan"' }));
    const dialog = document.querySelector('dialog');
    if (dialog === null) {
      throw new Error('Dialog did not render a <dialog> element');
    }
    // jsdom does not emulate the native Escape key, so the cancel event is dispatched directly.
    fireEvent(dialog, new Event('cancel', { cancelable: true }));

    expect(dialogIsOpen()).toBe(false);
    expect(removed).toEqual([]);
    expect(screen.getByRole('link', { name: 'Plan' })).toBeTruthy();
  });
});

import { useCallback, useEffect, useState } from 'react';
import {
  useDocumentStore,
  type DocumentSummary,
  type Result,
  type StoreError,
} from '@/features/documents';

export type DocumentListState =
  { kind: 'loading' } | { kind: 'error' } | { kind: 'ready'; documents: DocumentSummary[] };

export interface UseDocumentsResult {
  state: DocumentListState;
  // Shows the loading state and re-runs the read after an error (D14).
  retry: () => void;
  // Re-runs the read after a mutation such as delete (H5). Keeps the visible list while it reads,
  // so the spinner never flashes over data the user is looking at.
  reload: () => void;
}

function toListState(result: Result<DocumentSummary[], StoreError>): DocumentListState {
  if (result.ok) {
    return { kind: 'ready', documents: result.value };
  }
  return { kind: 'error' };
}

// H1: reads the document index only. A failed read becomes the error state, never a blank screen (D14).
export function useDocuments(): UseDocumentsResult {
  const store = useDocumentStore();
  const [state, setState] = useState<DocumentListState>({ kind: 'loading' });
  const [readCount, setReadCount] = useState(0);

  useEffect(() => {
    let active = true;
    store.list().then(
      (result) => {
        if (active) {
          setState(toListState(result));
        }
      },
      () => {
        if (active) {
          setState({ kind: 'error' });
        }
      },
    );
    return () => {
      active = false;
    };
  }, [store, readCount]);

  const retry = useCallback((): void => {
    setState({ kind: 'loading' });
    setReadCount((count) => count + 1);
  }, []);

  const reload = useCallback((): void => {
    setReadCount((count) => count + 1);
  }, []);

  return { state, retry, reload };
}

import { fireEvent, render, screen, waitFor, within } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { createMemoryRouter, RouterProvider, type DataRouter } from 'react-router';
import { describe, expect, it } from 'vitest';
import { setViewportWidth } from '@/test/matchMedia';
import {
  DocumentStoreProvider,
  type DocumentStore,
  type DocumentSummary,
} from '@/features/documents';
import { HomePage } from './HomePage';
import { fakeStore } from './testStore';

const PLAN: DocumentSummary = { id: 'doc-plan', title: 'Plan', preview: 'Goals', updatedAt: 0 };
const NEW_ID = 'new-doc-1';

function renderHome(store: DocumentStore): DataRouter {
  const router = createMemoryRouter(
    [
      { path: '/', element: <HomePage newId={() => NEW_ID} /> },
      { path: '/documents/:id', element: <p>Editor</p> },
    ],
    { initialEntries: ['/'] },
  );
  render(
    <DocumentStoreProvider store={store}>
      <RouterProvider router={router} />
    </DocumentStoreProvider>,
  );
  return router;
}

describe('HomePage', () => {
  // H1: while the index loads, a status spinner holds the space.
  it('shows the loading spinner before the documents arrive (H1)', async () => {
    const store = fakeStore([{ ok: true, value: [PLAN] }]);
    renderHome(store);

    expect(screen.getByRole('status').textContent).toBe('Loading documents');
    await screen.findByRole('link', { name: 'Plan' });
    expect(screen.queryByRole('status')).toBeNull();
  });

  // H1: documents link to their editor route.
  it('lists each document as a link to its editor route (H1)', async () => {
    renderHome(fakeStore([{ ok: true, value: [PLAN] }]));

    const link = await screen.findByRole('link', { name: 'Plan' });
    expect(link.getAttribute('href')).toBe('/documents/doc-plan');
    expect(screen.getByText('Goals')).toBeTruthy();
    expect(screen.getByText(/Edited /)).toBeTruthy();
  });

  // H4: cards are the default view; the toggle switches to rows and keeps the same links.
  // The preview belongs to the grid cards only (H4), so it disappears in the list.
  it('shows cards by default and switches to rows with the view toggle (H4, S7)', async () => {
    const user = userEvent.setup();
    renderHome(fakeStore([{ ok: true, value: [PLAN] }]));

    await screen.findByRole('link', { name: 'Plan' });
    const toggle = screen.getByRole('group', { name: 'Document view' });
    const gridButton = within(toggle).getByRole('button', { name: 'Grid' });
    const listButton = within(toggle).getByRole('button', { name: 'List' });
    expect(gridButton.getAttribute('aria-pressed')).toBe('true');
    expect(listButton.getAttribute('aria-pressed')).toBe('false');
    expect(screen.getByTestId('document-grid')).toBeTruthy();
    expect(screen.getByText('Goals')).toBeTruthy();

    await user.click(listButton);

    expect(listButton.getAttribute('aria-pressed')).toBe('true');
    expect(gridButton.getAttribute('aria-pressed')).toBe('false');
    expect(screen.queryByTestId('document-grid')).toBeNull();
    expect(screen.getByTestId('document-list')).toBeTruthy();
    expect(screen.queryByText('Goals')).toBeNull();
    expect(screen.getByRole('link', { name: 'Plan' }).getAttribute('href')).toBe(
      '/documents/doc-plan',
    );
  });

  // H6: with no documents, an invitation replaces the list.
  it('shows the empty invitation with a New document action (H6)', async () => {
    renderHome(fakeStore([{ ok: true, value: [] }]));

    await screen.findByRole('heading', { level: 2, name: 'Start your first document' });
    expect(screen.queryByRole('list')).toBeNull();
  });

  // H5: New document opens an editor route for a fresh id; nothing is saved here.
  it('New document in the empty state opens the editor with a new id (H5)', async () => {
    const user = userEvent.setup();
    const router = renderHome(fakeStore([{ ok: true, value: [] }]));

    const main = await screen.findByRole('main');
    await user.click(within(main).getByRole('button', { name: 'New document' }));

    await waitFor(() => {
      expect(router.state.location.pathname).toBe(`/documents/${NEW_ID}`);
    });
  });

  // D14: a failed read shows the error with Retry; only the sentence is the alert.
  it('shows the error with Retry and keeps the heading when the read fails (D14)', async () => {
    const user = userEvent.setup();
    renderHome(
      fakeStore([
        { ok: false, error: { kind: 'corrupt' } },
        { ok: true, value: [PLAN] },
      ]),
    );

    await screen.findByRole('heading', { level: 2, name: 'Could not load your documents' });
    expect(screen.getByRole('heading', { level: 1, name: 'Documents' })).toBeTruthy();
    expect(screen.getByRole('alert').textContent).toBe('Storage could not be read. Try again.');

    await user.click(screen.getByRole('button', { name: 'Retry' }));

    await screen.findByRole('link', { name: 'Plan' });
  });

  // H2: the sidebar keeps Pinned, Collaborations and Archive visible but disabled, with Soon labels.
  it('shows Pinned, Collaborations and Archive as disabled with a Soon label (H2)', () => {
    renderHome(fakeStore([{ ok: true, value: [] }]));

    const nav = screen.getByRole('navigation', { name: 'Primary' });
    for (const label of ['Pinned', 'Collaborations', 'Archive']) {
      const item = within(nav).getByRole('button', { name: new RegExp(label) });
      expect(item.getAttribute('aria-disabled')).toBe('true');
      expect(within(item).getByText('Soon')).toBeTruthy();
    }
    expect(within(nav).getByRole('link', { name: 'Documents' }).getAttribute('aria-current')).toBe(
      'page',
    );
  });

  // H2: a plain click on Documents is handled in-app (no full reload); modified clicks keep the
  // browser default, so the real href can open a new tab.
  it('handles a plain click on Documents in-app and keeps modified clicks native (H2)', () => {
    renderHome(fakeStore([{ ok: true, value: [] }]));
    const link = screen.getByRole('link', { name: 'Documents' });

    // fireEvent returns false when the default action was prevented.
    expect(fireEvent.click(link)).toBe(false);
    expect(fireEvent.click(link, { ctrlKey: true })).toBe(true);
    expect(fireEvent.click(link, { button: 1 })).toBe(true);
  });

  // S9: at phone width the sidebar is a drawer; New document is reachable inside it (H2).
  it('puts New document inside the drawer at 360px (S9, H2)', async () => {
    setViewportWidth(360);
    const user = userEvent.setup();
    const router = renderHome(fakeStore([{ ok: true, value: [] }]));

    await user.click(screen.getByRole('button', { name: 'Open navigation' }));
    const nav = screen.getByRole('navigation', { name: 'Primary' });
    await user.click(within(nav).getByRole('button', { name: 'New document' }));

    await waitFor(() => {
      expect(router.state.location.pathname).toBe(`/documents/${NEW_ID}`);
    });
  });
});

import type { JSX } from 'react';
import { useCallback, useRef, useState } from 'react';
import { useNavigate } from 'react-router';
import { AppShell, Button, EmptyState, Spinner } from '@/design-system';
import type { DocumentSummary } from '@/features/documents';
import { DeleteDocumentDialog } from './DeleteDocumentDialog';
import { DocumentGrid } from './DocumentGrid';
import { DocumentList } from './DocumentList';
import { EmptyHome } from './EmptyHome';
import { HomeNavbar } from './HomeNavbar';
import { HomeSidebar } from './HomeSidebar';
import type { DocumentListState } from './useDocuments';
import { useDocuments } from './useDocuments';
import { useDeleteDocument } from './useDeleteDocument';
import { ViewToggle, type DocumentView } from './ViewToggle';
import './home.css';
import './views.css';

export interface HomePageProps {
  // Injected by tests; the default is a random UUID, which the editor route accepts (H5).
  newId?: () => string;
  // Injected by tests; the default is the current time, read once per render (H4 "Edited x ago").
  now?: number;
}

interface DocumentsPanelOptions {
  view: DocumentView;
  now: number;
  onViewChange: (view: DocumentView) => void;
  onRetry: () => void;
  onNewDocument: () => void;
  onDelete: (doc: DocumentSummary) => void;
}

function createDocumentId(): string {
  return crypto.randomUUID();
}

function renderDocuments(state: DocumentListState, options: DocumentsPanelOptions): JSX.Element {
  if (state.kind === 'loading') {
    return (
      <div className="home-page__loading">
        <Spinner label="Loading documents" />
      </div>
    );
  }
  if (state.kind === 'error') {
    // The alert wraps only the sentence; the heading and Retry stay outside it (D14).
    return (
      <EmptyState
        title="Could not load your documents"
        action={
          <div className="home-page__error">
            <p role="alert" className="home-page__error-text">
              Storage could not be read. Try again.
            </p>
            <Button onClick={options.onRetry}>Retry</Button>
          </div>
        }
      />
    );
  }
  if (state.documents.length === 0) {
    return <EmptyHome onNewDocument={options.onNewDocument} />;
  }
  return (
    <>
      <ViewToggle value={options.view} onChange={options.onViewChange} />
      {options.view === 'grid' ? (
        <DocumentGrid documents={state.documents} now={options.now} onDelete={options.onDelete} />
      ) : (
        <DocumentList documents={state.documents} now={options.now} onDelete={options.onDelete} />
      )}
    </>
  );
}

// H1-H4, H6: the app's first screen. Every read state is rendered; none blanks the page (D14).
export function HomePage({ newId = createDocumentId, now }: HomePageProps): JSX.Element {
  const navigate = useNavigate();
  const { state, retry, reload } = useDocuments();
  const [view, setView] = useState<DocumentView>('grid');
  // Read once when the page mounts: relative times stay stable across re-renders (purity). They do
  // not refresh while the page stays open; this is accepted for now (H4).
  const [renderedAt] = useState(() => now ?? Date.now());
  const headingRef = useRef<HTMLHeadingElement>(null);
  // Set when a delete succeeds, so the dialog's close moves focus to the heading (the removed
  // card's button can no longer take it).
  const deletedRef = useRef(false);
  const deletion = useDeleteDocument({
    onDeleted: () => {
      deletedRef.current = true;
      reload();
    },
  });

  const returnFocusOnClose = useCallback((): HTMLElement | null => {
    const deleted = deletedRef.current;
    deletedRef.current = false;
    return deleted ? headingRef.current : null;
  }, []);

  function startNewDocument(): void {
    void navigate(`/documents/${newId()}`);
  }

  return (
    <AppShell navbar={<HomeNavbar />} sidebar={<HomeSidebar onNewDocument={startNewDocument} />}>
      <div className="home-page">
        <h1 ref={headingRef} tabIndex={-1} className="home-page__title">
          Documents
        </h1>
        {renderDocuments(state, {
          view,
          now: renderedAt,
          onViewChange: setView,
          onRetry: retry,
          onNewDocument: startNewDocument,
          onDelete: deletion.request,
        })}
        <DeleteDocumentDialog
          state={deletion.state}
          onConfirm={deletion.confirm}
          onCancel={deletion.cancel}
          onCloseFocus={returnFocusOnClose}
        />
      </div>
    </AppShell>
  );
}

