    if (isOpen) {
      close();
      return;
    }
    openOnSelection();
  }

  function handleTriggerKeyDown(event: ReactKeyboardEvent<HTMLButtonElement>): void {
    if (event.key === LIST_KEY.arrowDown) {
      event.preventDefault();
      openOnSelection();
    } else if (event.key === LIST_KEY.arrowUp) {
      event.preventDefault();
      open(lastEnabledIndex(options));
    }
