      return;
    }
    if (event.key === LIST_KEY.enter || event.key === LIST_KEY.space) {
      event.preventDefault();
      choose(activeIndex);
      return;
    }
    const target = navigationTarget(options, activeIndex, event.key);
    if (target !== undefined) {
      event.preventDefault();
      if (target >= 0) {
        moveTo(target);
      }
      return;
    }
