   surface is a clean page: no box or border around the text (prototype .page). */
.editor-surface {
  display: flex;
  flex: 1 0 auto;
  flex-direction: column;
  min-block-size: 0;
  min-inline-size: 0;
  max-inline-size: 75ch;
  inline-size: 100%;
}

.editor-surface .ProseMirror {
  display: block;
