  margin-block-start: var(--ds-space-100);
}

/* Headings keep clear of the "Improve section" control at the inline end (HeadingActions), so the
   control never sits over the heading text. The reserved width is two tokens: 80px plus 48px. */
.editor-surface .ProseMirror h1,
.editor-surface .ProseMirror h2,
.editor-surface .ProseMirror h3 {
  padding-inline-end: calc(var(--ds-space-1000) + var(--ds-space-600));
}

.editor-surface .ProseMirror h1 {
  font: var(--ds-font-heading-large);
}

/* The document's first block reads as its title (prototype h1.dt): large, bold, tight tracking. */
.editor-surface .ProseMirror > h1:first-child {
  font: var(--ds-font-heading-xxlarge);
  letter-spacing: -0.02em;
  margin-block-end: var(--ds-space-200);
}

.editor-surface .ProseMirror h2 {
  font: var(--ds-font-heading-medium);
}

.editor-surface .ProseMirror h3 {
  font: var(--ds-font-heading-small);
}

