import type { JSX } from 'react';
import { BottomSheet } from '@/design-system';
import type { HistoryEntry } from '@/features/documents';
import { HistoryTimeline } from './HistoryTimeline';

export interface HistoryPanelProps {
  open: boolean;
  onClose: () => void;
  // Oldest first, as stored.
  entries: readonly HistoryEntry[];
  now: number;
  onRestore: (entryId: string) => void;
}

// D7: the version history. A bottom sheet at every width, so touch and keyboard share one path.
// This is a deliberate deviation from the popover used for flags (S9): the timeline is long.
export function HistoryPanel({
  open,
  onClose,
  entries,
  now,
  onRestore,
}: HistoryPanelProps): JSX.Element {
  return (
    <BottomSheet open={open} onClose={onClose} label="Version history">
      {open ? <HistoryTimeline entries={entries} now={now} onRestore={onRestore} /> : null}
    </BottomSheet>
  );
}
/* S2: spacing, type and colour from tokens only. */
.history-entry {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--ds-space-100);
  padding-block: var(--ds-space-100);
  padding-inline-start: var(--ds-space-150);
  border-inline-start: 2px solid var(--ds-border);
}

/* AI entries take the accent rule (prototype .hist .ai), so AI work reads apart from the author's. */
.history-entry--ai {
  border-inline-start-color: var(--ds-border-information);
}

.history-entry__body {
  min-inline-size: 0;
}

.history-entry__label,
.history-entry__meta {
  margin: 0;
  overflow-wrap: anywhere;
}

.history-entry__label {
  font: var(--ds-font-body-small);
  font-weight: var(--ds-font-weight-medium);
  color: var(--ds-text);
}

.history-entry__meta {
  font: var(--ds-font-body-small);
  color: var(--ds-text-subtle);
}

/* S9: touch targets are at least 44px on coarse pointers. */
@media (pointer: coarse) {
  .history-entry .ds-button {
    min-block-size: 44px;
    min-inline-size: 44px;
  }
}
/* S2: spacing, type and colour from tokens only. */
.history-timeline {
  display: grid;
  gap: var(--ds-space-100);
  max-inline-size: 22rem;
}

.history-timeline__panel {
  display: grid;
  gap: var(--ds-space-100);
}

.history-timeline__panel[hidden] {
  display: none;
}

.history-timeline__list {
  margin: 0;
  padding: 0;
  list-style: none;
  display: grid;
  gap: var(--ds-space-050);
}

.history-timeline__empty {
  margin: 0;
  font: var(--ds-font-body);
  color: var(--ds-text-subtle);
}
