/* S2, S9: tokens only. The prototype's 13px card text maps to the body-small token, and the
   pills and rows sit in the suggestion card owned by FlagPanel. */
.refine {
  display: flex;
  flex-direction: column;
  gap: var(--ds-space-075);
  margin-block-start: var(--ds-space-100);
  font: var(--ds-font-body-small);
  color: var(--ds-text);
}

.refine__row,
.refine__nav {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--ds-space-075);
}

.refine__select {
  flex: 0 0 auto;
}

/* The field takes the free width; the Refine button keeps its size beside it. */
.refine__field {
  flex: 1 1 160px;
  min-inline-size: 0;
}

.refine__count {
  margin-inline-start: auto;
  color: var(--ds-text-subtle);
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
}

/* S9: 44px touch targets on coarse pointers. */
@media (pointer: coarse) {
  .refine .ds-button,
  .refine .ds-select__trigger {
    min-block-size: 44px;
  }
}
/* S2, S5, S7, S9: tokens only. The listbox panel itself is styled by Popover.css. Control heights
   (32px, 44px on coarse pointers) have no token in tokens.css yet; they match Button.css. */
.ds-select__trigger {
  display: inline-flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--ds-space-050);
  min-block-size: 32px;
  padding-inline: var(--ds-space-150) var(--ds-space-100);
  border: var(--ds-border-width) solid var(--ds-border-input);
  border-radius: var(--ds-radius-small);
  background: var(--ds-background-input);
  color: var(--ds-text);
  font: var(--ds-font-body);
  cursor: pointer;
}

.ds-select__trigger:hover {
  background: var(--ds-background-input-hovered);
}

/* The open trigger gets a bolder border, so open is visible without relying on color alone. */
.ds-select__trigger[aria-expanded='true'] {
  border-color: var(--ds-border-bold);
}

.ds-select__value {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* The placeholder is text in the subtle color, so the empty state reads as a prompt (S7). */
.ds-select__value--placeholder {
  color: var(--ds-text-subtle);
}

/* A drawn chevron, so the trigger reads as a dropdown without an icon outside the icon set. */
.ds-select__chevron {
  flex-shrink: 0;
  inline-size: var(--ds-space-100);
  block-size: var(--ds-space-100);
  border-inline-end: var(--ds-border-width) solid currentColor;
  border-block-end: var(--ds-border-width) solid currentColor;
  transform: translateY(-25%) rotate(45deg);
  transition: transform var(--ds-duration-short) var(--ds-easing-out-practical);
}

.ds-select__trigger[aria-expanded='true'] .ds-select__chevron {
  transform: translateY(25%) rotate(225deg);
}

@media (prefers-reduced-motion: reduce) {
  .ds-select__chevron {
    transition: none;
  }
}

.ds-select__list {
  display: flex;
  flex-direction: column;
  gap: var(--ds-space-025);
}

.ds-select__option {
  display: flex;
  align-items: center;
  gap: var(--ds-space-050);
  min-block-size: 32px;
  padding-inline: var(--ds-space-050) var(--ds-space-100);
  border-radius: var(--ds-radius-small);
  color: var(--ds-text);
  font: var(--ds-font-body);
  cursor: pointer;
  user-select: none;
}

import type { JSX } from 'react';
import { Spinner } from '@/design-system';
import type { SuggestionFailure, SuggestionRequest } from './suggestionRequest';

export type SuggestionOutcomeRequest = SuggestionRequest;

// D14: plain, factual one-liners. The model's text is never shown here.
const FAILURE_TEXT: Record<SuggestionFailure, string> = {
  out_of_credit: 'The AI is out of credit.',
  unavailable: 'The AI is unavailable. Try again later.',
  stale: 'The text changed after this suggestion was written.',
};

export interface SuggestionOutcomeProps {
  request: SuggestionOutcomeRequest;
}

// The body of the card for each state of the request (D14, T10).
export function SuggestionOutcome({ request }: SuggestionOutcomeProps): JSX.Element {
  switch (request.kind) {
    case 'loading':
      return <Spinner label="Writing a suggestion" />;
    case 'ready':
      return <p className="suggestion-card__note">The change is shown in the text.</p>;
    case 'empty':
      return <p className="suggestion-card__note">No changes suggested</p>;
    case 'error':
      return (
        <>
          <p className="suggestion-card__note">Your text is unchanged.</p>
          <p className="suggestion-card__note">{FAILURE_TEXT[request.reason]}</p>
        </>
      );
  }
}
/* D5, S7: the diff is shown with a strike (removed) and an underline (added), so it never relies
   on colour alone. Colours are the diff tokens from tokens.css (S2). */
.ProseMirror .suggestion-delete {
  text-decoration-line: line-through;
  background-color: var(--ai-diff-delete-bg);
}

.ProseMirror .suggestion-insert {
  text-decoration-line: underline;
  background-color: var(--ai-diff-insert-bg);
}

.suggestion-card {
  display: grid;
  gap: var(--ds-space-100);
  inline-size: min(23.75rem, 100%);
  box-sizing: border-box;
  outline: none;
}

/* Reserves the outcome's height so the spinner, note and error text do not move the buttons. */
.suggestion-card__outcome {
  display: grid;
  align-content: center;
  min-block-size: var(--ds-space-600);
}

.suggestion-card__note {
  margin: 0;
  font: var(--ds-font-body-small);
  color: var(--ds-text-subtle);
}

.suggestion-card__actions {
  display: flex;

