}

.ds-select__value {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* The placeholder is text in the subtle color, so the empty state reads as a prompt (S7). */
.ds-select__value--placeholder {
  color: var(--ds-text-subtle);
}

/* A drawn chevron, so the trigger reads as a dropdown without an icon outside the icon set. */
.ds-select__chevron {
