  inline-size: var(--ds-space-100);
  block-size: var(--ds-space-100);
  border-inline-end: var(--ds-border-width) solid currentColor;
  border-block-end: var(--ds-border-width) solid currentColor;
  transform: translateY(-25%) rotate(45deg);
  transition: transform var(--ds-duration-short) var(--ds-easing-out-practical);
}

.ds-select__trigger[aria-expanded='true'] .ds-select__chevron {
