import { StrictMode } from 'react';
import { createRoot } from 'react-dom/client';
import { App } from '@/App';
import { AiServicesProvider } from '@/app/AiServicesProvider';
import { watchColorScheme } from '@/design-system';
import { createLocalStorageStore, DocumentStoreProvider } from '@/features/documents';
import './design-system/tokens.css';

const ROOT_ELEMENT_ID = 'root';
const DARK_SCHEME_QUERY = '(prefers-color-scheme: dark)';

function getRootElement(): HTMLElement {
  const element = document.getElementById(ROOT_ELEMENT_ID);
  if (element === null) {
    throw new Error(`Root element #${ROOT_ELEMENT_ID} was not found in index.html`);
  }
  return element;
}

watchColorScheme(document.documentElement, window.matchMedia(DARK_SCHEME_QUERY));

const store = createLocalStorageStore({ storage: window.localStorage });

createRoot(getRootElement()).render(
  <StrictMode>
    <DocumentStoreProvider store={store}>
      <AiServicesProvider>
        <App />
      </AiServicesProvider>
    </DocumentStoreProvider>
  </StrictMode>,
);
export { Icon, type IconName, type IconProps } from './icons';
export {
  applyTheme,
  watchColorScheme,
  type ColorMode,
  type ColorSchemeSource,
  type ThemeRoot,
} from './theme';
export {
  AppShell,
  Avatar,
  BottomSheet,
  Button,
  Dialog,
  EmptyState,
  IconButton,
  IconLink,
  Lozenge,
  Menu,
  NavItem,
  Popover,
  Select,
  iconLinkClassName,
  Spinner,
  TextField,
  ToggleGroup,
  VisuallyHidden,
  useShell,
  type AppShellProps,
  type AvatarProps,
  type AvatarSize,
  type BottomSheetProps,
  type ButtonProps,
  type ButtonVariant,
  type DialogProps,
  type EmptyStateProps,
  type IconButtonProps,
  type IconLinkProps,
  type LozengeProps,
  type LozengeTone,
  type MenuItem,
  type MenuProps,
  type MenuTrigger,
  type NavItemProps,
  type PopoverPlacement,
  type PopoverProps,
  type SelectOption,
  type SelectProps,
  type ShellState,
  type SpinnerProps,
  type TextFieldProps,
  type ToggleGroupOption,
  type ToggleGroupProps,
  type VisuallyHiddenProps,
} from './components';
export { BREAKPOINTS, useBreakpoint, type Breakpoint, type ViewportBreakpoint } from './responsive';
import type { JSX } from 'react';
import { Link } from 'react-router';
import { Avatar, Icon, TextField } from '@/design-system';

const PRODUCT_NAME = 'WebApp';
// The mark shows the first letter of the product name, so the two never drift apart.
const MARK_LETTER = PRODUCT_NAME.charAt(0);
const SEARCH_PLACEHOLDER = 'Search documents';
// H3: the disabled search explains itself on hover (the native disabled field cannot take focus).
const SEARCH_UNAVAILABLE = 'Search is coming later';

// H3: product name, a visible but disabled search with a "Soon" label, and a placeholder user.
export function HomeNavbar(): JSX.Element {
  return (
    <div className="home-navbar">
      <Link to="/" className="home-navbar__name">
        <span className="home-navbar__mark" aria-hidden="true">
          {MARK_LETTER}
        </span>
        {PRODUCT_NAME}
      </Link>
      <div className="home-navbar__search" title={SEARCH_UNAVAILABLE}>
        <div className="home-navbar__field">
          <span className="home-navbar__search-icon">
            <Icon name="search" size={16} />
          </span>
          <TextField
            label={SEARCH_PLACEHOLDER}
            hideLabel
            type="search"
            disabled
            aria-disabled="true"
            placeholder={SEARCH_PLACEHOLDER}
          />
        </div>
      </div>
      <div className="home-navbar__user">
        <Avatar name="You" />
      </div>
    </div>
  );
}
import type { JSX, ReactNode } from 'react';
import { Link } from 'react-router';
import { Button, Icon, iconLinkClassName, useBreakpoint } from '@/design-system';
import { AiModeToggle } from './AiModeToggle';
import { EditorOverflowMenu } from './EditorOverflowMenu';
import type { AiMode, ViewMode } from './editorModes';
import { ViewModeToggle } from './ViewModeToggle';

// The controls that exist once the document is open.
export interface EditorViewControls {
  viewMode: ViewMode;
  onViewModeChange: (mode: ViewMode) => void;
  aiMode: AiMode;
  onAiModeChange: (mode: AiMode) => void;
  // Opens the version history (D7).
  onHistory: () => void;
}

export interface EditorTopBarProps {
  // Text for the save live region; empty when there is nothing to announce.
  message: string;
  // The title field; absent while the document is loading or cannot be opened.
  title?: ReactNode;
  // Absent while the document is loading or cannot be opened.
  view?: EditorViewControls | undefined;
  // The AI status indicator (D14); absent while the document is loading.
  aiStatus?: ReactNode;
  // The Next flag control (D17); the caller shows it only while a flag exists.
  flagControl?: ReactNode;
}

// H5, D1, D15, H7, S9: back and app name, the title, the view and AI mode toggles, and the save
// status. Below md the view toggle and History move into the overflow menu. The AI status and the
// flag control have reserved widths, so their appearing or changing does not move the toggles.
export function EditorTopBar({
  message,
  title,
  view,
  aiStatus,
  flagControl,
}: EditorTopBarProps): JSX.Element {
  const breakpoint = useBreakpoint();
  const compact = breakpoint === 'base' || breakpoint === 'sm';

  return (
    <header className="editor-top-bar">
      <Link to="/" aria-label="Back to documents" className={iconLinkClassName()}>
        <Icon name="arrow-left" />
      </Link>
      <Link to="/" className="editor-top-bar__name">
        <span className="editor-top-bar__mark" aria-hidden="true">
          W
        </span>
        WebApp
      </Link>
      {view !== undefined && compact ? (
        <div className="editor-top-bar__overflow">
          <EditorOverflowMenu
            viewMode={view.viewMode}
            onViewModeChange={view.onViewModeChange}
            onHistory={view.onHistory}
          />
        </div>
      ) : null}
      {title === undefined ? null : <div className="editor-top-bar__title">{title}</div>}
      <div className="editor-top-bar__toggles">
        {view !== undefined && !compact ? (
          <ViewModeToggle value={view.viewMode} onChange={view.onViewModeChange} />
        ) : null}
        {view !== undefined ? (
          <AiModeToggle value={view.aiMode} onChange={view.onAiModeChange} />
        ) : null}
        {view !== undefined && !compact ? <Button onClick={view.onHistory}>History</Button> : null}
      </div>
      <div className="editor-top-bar__flags">{flagControl ?? null}</div>
      <div className="editor-top-bar__ai">{aiStatus ?? null}</div>
      <p role="status" className="editor-top-bar__status">
        {message}
      </p>
    </header>
  );
}
import { describe, expect, it } from 'vitest';
import {
  THEME_ATTRIBUTE_VALUE,
  applyTheme,
  watchColorScheme,
  type ColorSchemeSource,
  type ThemeRoot,
