  const calls: PendingCall[] = [];
  const run = vi.fn(
    (request: AiRequestOf<'analyze'>, signal?: AbortSignal) =>
      new Promise<AiClientResult<'analyze'>>((resolve) => {
        calls.push({ request, signal, respond: resolve });
      }),
  );
  return { run, calls };
};

