import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { describe, expect, it, vi } from 'vitest';
import type { JSX } from 'react';
import { useEffect } from 'react';
import {
  AiStatusProvider,
  createAiClient,
  createAiStatusStore,
  type AiStatusStore,
  type FetchLike,
} from '@/features/ai';
import { fnv1a32 } from '@/lib/hash';
import type { Flag } from '@shared/schemas';
import { useAnalyzeScheduler, type AnalyzeSchedulerHandle } from './useAnalyzeScheduler';
import type { ParagraphContext } from './paragraphContext';

// T9: the AI is faked at the fetch boundary; the real client and status store run on top of it.
const PARAGRAPH = 'The launch moved to the second week of March.';
const FLAG: Flag = { kind: 'clarity', quote: 'moved', reason: 'Say why the date changed.' };
const CONTEXT: ParagraphContext = { id: 'p1', text: PARAGRAPH };

const jsonResponse = (status: number, body: unknown): Response =>
  new Response(JSON.stringify(body), {
    status,
    headers: { 'Content-Type': 'application/json' },
  });

type OnFlags = (hash: string, flags: Flag[]) => void;

interface HarnessProps {
  paused: boolean;
  onFlags: OnFlags;
  onHandle: (handle: AnalyzeSchedulerHandle) => void;
}

// Buttons stand in for the editor: an edit followed by leaving the paragraph is what analyzes it.
function Harness({ paused, onFlags, onHandle }: HarnessProps): JSX.Element {
  const handle = useAnalyzeScheduler({ paused, onFlags, isLive: () => true });
  useEffect(() => {
    onHandle(handle);
  }, [handle, onHandle]);
  return (
    <>
      <button
        type="button"
        onClick={() => {
          handle.paragraphEdited(CONTEXT);
        }}
      >
        Edit paragraph
      </button>
      <button
        type="button"
        onClick={() => {
          handle.paragraphLeft(CONTEXT);
        }}
      >
        Leave paragraph
      </button>
    </>
  );
}

interface RenderOptions {
  paused?: boolean;
  store?: AiStatusStore;
  fetchImpl: FetchLike;
}

const renderHarness = ({
  paused = false,
  store = createAiStatusStore(),
  fetchImpl,
}: RenderOptions) => {
  const onFlags = vi.fn<OnFlags>();
  const handles: AnalyzeSchedulerHandle[] = [];
  const client = createAiClient({ fetchImpl });
  const result = render(
    <AiStatusProvider client={client} store={store}>
      <Harness
        paused={paused}
        onFlags={onFlags}
        onHandle={(handle) => {
          handles.push(handle);
        }}
      />
    </AiStatusProvider>,
  );
  return { ...result, onFlags, handles, store };
};

// Edits the paragraph, then leaves it, the way the editor reports it.
const editAndLeave = async (): Promise<void> => {
  await userEvent.click(screen.getByRole('button', { name: 'Edit paragraph' }));
  await userEvent.click(screen.getByRole('button', { name: 'Leave paragraph' }));
};

describe('useAnalyzeScheduler (D4, D1, D14, D15, T10)', () => {
  it('emits the flags for the edited paragraph once it is left', async () => {
    const fetchImpl = vi.fn<FetchLike>(() => Promise.resolve(jsonResponse(200, { flags: [FLAG] })));
    const { onFlags } = renderHarness({ fetchImpl });
    await editAndLeave();
    await waitFor(() => {
      expect(onFlags).toHaveBeenCalledWith(fnv1a32(PARAGRAPH), [FLAG]);
    });
    expect(fetchImpl).toHaveBeenCalledTimes(1);
  });

  it('makes no call while paused in On Demand mode or the raw view (D1, D15)', async () => {
    const fetchImpl = vi.fn<FetchLike>(() => Promise.resolve(jsonResponse(200, { flags: [FLAG] })));
    const { onFlags } = renderHarness({ paused: true, fetchImpl });
    await editAndLeave();
    expect(fetchImpl).not.toHaveBeenCalled();
    expect(onFlags).not.toHaveBeenCalled();
  });

  it('keeps analyzing after an outage, since the next request can recover (D14)', async () => {
    const fetchImpl = vi.fn<FetchLike>(() => Promise.resolve(jsonResponse(200, { flags: [FLAG] })));
    const store = createAiStatusStore();
    store.begin();
    store.end({ ok: false, error: { kind: 'unavailable' } });
    const { onFlags } = renderHarness({ store, fetchImpl });
    await editAndLeave();
    await waitFor(() => {
      expect(onFlags).toHaveBeenCalledTimes(1);
    });
    expect(store.getSnapshot()).toBe('ready');
  });

  it('stops calling and emits nothing once out of credit (D14)', async () => {
    const fetchImpl = vi.fn<FetchLike>(() =>
      Promise.resolve(
        jsonResponse(402, { error: { code: 'out_of_credit', message: 'No credit.' } }),
      ),
    );
    const store = createAiStatusStore();
    const { onFlags } = renderHarness({ store, fetchImpl });
    await editAndLeave();
    await waitFor(() => {
      expect(store.getSnapshot()).toBe('out_of_credit');
    });
    await editAndLeave();
    expect(fetchImpl).toHaveBeenCalledTimes(1);
    expect(onFlags).not.toHaveBeenCalled();
  });

  it('stops scheduling after unmount (cleanup on unmount)', () => {
    const fetchImpl = vi.fn<FetchLike>(() => Promise.resolve(jsonResponse(200, { flags: [FLAG] })));
    const { handles, unmount } = renderHarness({ fetchImpl });
    const handle = handles[0];
    expect(handle).toBeDefined();
    unmount();
    handle?.paragraphEdited(CONTEXT);
    handle?.paragraphLeft(CONTEXT);
    expect(fetchImpl).not.toHaveBeenCalled();
  });
});

import type { JSX } from 'react';
import type { Editor } from '@tiptap/react';
import { BottomSheet, Popover, useBreakpoint } from '@/design-system';
import { FlagPanel, KIND_LABELS } from './FlagPanel';
import { clearFlagsMeta } from './flags/flagsPlugin';
import { serializeMarkdown } from './markdown/markdown';
import type { FlagEntry } from './flags/flagsState';
import { applySuggestion } from './suggestion/applySuggestion';
import { refineControlsFor } from './suggestion/refineControlsFor';
import { rewriteTargetOf, type RewriteTarget } from './suggestion/rewriteTarget';
import { SuggestionCard } from './suggestion/SuggestionCard';
import { getSuggestion } from './suggestion/suggestionPlugin';
import type { RewriteSession, RoundPick } from './suggestion/useRewriteSession';
import { useFlags } from './useFlags';

const FLAG_DIALOG_LABEL = 'Writing flag';
const SUGGESTION_DIALOG_LABEL = 'Suggestion';
// D6 default for "View Suggestion": the AI picks the tone.
const FLAG_VIEW_PICK: RoundPick = { type: 'setTone', tone: 'auto' };

export interface FlagPopoverProps {
  editor: Editor;
  // The flag whose popover is open, by id; null while no flag is open.
  flagId: string | null;
  // The rewrite in progress (D5, D9). It shows in this popover, anchored to its text.
  session: RewriteSession;
  onClose: () => void;
  // Reports an accepted rewrite: its card title, and the Markdown from before it (D7).
  onAccepted: (label: string, before: string) => void;
  onAnswer?: ((answer: string) => void) | undefined;
}

// The flag's underline element. Read on each render: useFlags re-renders after every transaction,
// which is what replaces the decoration element.
function flagElementOf(editor: Editor, flagId: string): HTMLElement | null {
  return editor.view.dom.querySelector<HTMLElement>(`[data-flag-id="${flagId}"]`);
}

// The block element holding a document position, for a rewrite that is not tied to a flag.
function blockElementAt(editor: Editor, pos: number): HTMLElement | null {
  const { node } = editor.view.domAtPos(pos);
  const element = node instanceof HTMLElement ? node : node.parentElement;
  return element?.closest<HTMLElement>('p, h1, h2, h3, h4, h5, h6, li, blockquote') ?? null;
}

// The element the popover hangs from: the flag's underline, or the text a rewrite works on.
function anchorOf(
  editor: Editor,
  target: RewriteTarget | null,
  flagId: string | null,
): HTMLElement | null {
  if (target === null) {
    return flagId === null ? null : flagElementOf(editor, flagId);
  }
  if (target.flagId !== undefined) {
    return flagElementOf(editor, target.flagId);
  }
  return blockElementAt(editor, target.from);
}

interface PanelInputs {
  editor: Editor;
  session: RewriteSession;
  flag: FlagEntry | undefined;
  close: () => void;
  onAccepted: (label: string, before: string) => void;
  onAnswer: ((answer: string) => void) | undefined;
}

// The panel: the rewrite card while a rewrite is open, otherwise the flag (D5).
function panelFor({
  editor,
  session,
  flag,
  close,
  onAccepted,
  onAnswer,
}: PanelInputs): JSX.Element | null {
  const { target, outcome } = session;
  if (target !== null && outcome !== null) {
    const onAccept = (): void => {
      const current = getSuggestion(editor.state);
      if (current === null) {
        session.fail('stale');
        return;
      }
      const before = serializeMarkdown(editor);
      const result = applySuggestion(editor, current);
      if (result.ok) {
        onAccepted(target.title, before);
        close();
      } else {
        session.fail(result.reason);
      }
    };
    const onDismiss = (): void => {
      if (target.flagId !== undefined) {
        editor.view.dispatch(clearFlagsMeta(editor.state.tr, target.flagId));
      }
      close();
    };
    return (
      <SuggestionCard
        request={outcome}
        refine={refineControlsFor(session)}
        onAccept={onAccept}
        onDismiss={onDismiss}
      />
    );
  }
  if (flag === undefined) {
    return null;
  }
  return (
    <FlagPanel
      flag={flag}
      onDismiss={() => {
        editor.view.dispatch(clearFlagsMeta(editor.state.tr, flag.id));
        close();
      }}
      onViewSuggestion={() => {
        const flagTarget = rewriteTargetOf(editor.state.doc, flag, {
          title: KIND_LABELS[flag.kind],
          detail: flag.reason,
          flagId: flag.id,
        });
        if (flagTarget !== null) {
          session.start(flagTarget, FLAG_VIEW_PICK);
        }
      }}
      onAnswer={onAnswer}
    />
  );
}

// S9: a popover from md up, a bottom sheet below. Focus returns to the editor on close (D17).
// Closing ends the rewrite, so no preview is left behind (D5).
export function FlagPopover({
  editor,
  flagId,
  session,
  onClose,
  onAccepted,
  onAnswer,
}: FlagPopoverProps): JSX.Element {
  const breakpoint = useBreakpoint();
  const flag = useFlags(editor).find((entry) => entry.id === flagId);
  const { target } = session;
  const close = (): void => {
    session.stop();
    onClose();
  };

  const isOpen = target !== null || flag !== undefined;
  const anchor = anchorOf(editor, target, flagId);
  const label =
    target !== null && target.flagId === undefined ? SUGGESTION_DIALOG_LABEL : FLAG_DIALOG_LABEL;
  const returnFocusTo = (): HTMLElement => editor.view.dom;
  const panel = panelFor({ editor, session, flag, close, onAccepted, onAnswer });

  if (breakpoint === 'base' || breakpoint === 'sm') {
    return (
      <BottomSheet open={isOpen} onClose={close} label={label} returnFocusTo={returnFocusTo}>
        {panel}
      </BottomSheet>
    );
  }
  return (
    <Popover
      anchor={anchor}
      open={isOpen}
      onClose={close}
      label={label}
      returnFocusTo={returnFocusTo}
    >
      {panel}
    </Popover>
  );
}

