  --ds-background-selected-bold: #673286;
  --ds-background-selected-bold-hovered: #48245D;
  --ds-background-selected-bold-pressed: #35243F;
  --ds-border-brand: #803FA5;
  --ds-border-selected: #803FA5;
  --ds-border-focused: #964AC0;
  --ds-text-brand: #673286;
  --ds-text-selected: #673286;
  --ds-icon-brand: #673286;
  --ds-icon-selected: #673286;
  --ds-link: #673286;
