/* S5, S7: each kind differs by underline style, not only colour. Tokens only, so light and
   dark themes both apply. Focus rings belong to phase 35. */
.ProseMirror .flag {
  text-decoration-line: underline;
  text-decoration-thickness: 2px;
  text-underline-offset: 3px;
  text-decoration-color: var(--ai-flag-underline);
}

/* Clarity and wordiness: wavy. */
.ProseMirror .flag--clarity {
  text-decoration-style: wavy;
  text-decoration-color: var(--ds-border-information);
}

/* Tone consistency: dashed. */
.ProseMirror .flag--tone {
  text-decoration-style: dashed;
  text-decoration-color: var(--ds-border-discovery);
}

/* Grammar and typos: dotted. */
.ProseMirror .flag--grammar {
  text-decoration-style: dotted;
  text-decoration-color: var(--ds-border-danger);
}

/* Questions to the author: double. */
.ProseMirror .flag--question {
  text-decoration-style: double;
  text-decoration-color: var(--ds-border-success);
}
/* D5, S7: the diff is shown with a strike (removed) and an underline (added), so it never relies
   on colour alone. Colours are the diff tokens from tokens.css (S2). */
.ProseMirror .suggestion-delete {
  text-decoration-line: line-through;
  background-color: var(--ai-diff-delete-bg);
}

.ProseMirror .suggestion-insert {
  text-decoration-line: underline;
  background-color: var(--ai-diff-insert-bg);
}

.suggestion-card {
  display: grid;
  gap: var(--ds-space-100);
  inline-size: min(23.75rem, 100%);
  box-sizing: border-box;
  outline: none;
}

/* Reserves the outcome's height so the spinner, note and error text do not move the buttons. */
.suggestion-card__outcome {
  display: grid;
  align-content: center;
  min-block-size: var(--ds-space-600);

