import type { JSX } from 'react';
import { ToggleGroup } from '@/design-system';
import { VIEW_MODE_OPTIONS, toViewMode, type ViewMode } from './editorModes';

export interface ViewModeToggleProps {
  value: ViewMode;
  onChange: (mode: ViewMode) => void;
}

// D15: switches the document between the Visual editor and its raw Markdown.
export function ViewModeToggle({ value, onChange }: ViewModeToggleProps): JSX.Element {
  return (
    <ToggleGroup
      label="Editor view"
      value={value}
      options={VIEW_MODE_OPTIONS}
      onChange={(next) => {
        const mode = toViewMode(next);
        if (mode !== undefined) {
          onChange(mode);
        }
      }}
    />
  );
}
import type { JSX } from 'react';
import { ToggleGroup } from '@/design-system';
import { AI_MODE_OPTIONS, toAiMode, type AiMode } from './editorModes';

export interface AiModeToggleProps {
  value: AiMode;
  onChange: (mode: AiMode) => void;
}

// D1: Ambient or On Demand. Only the state is set here; the AI behavior arrives in later phases.
export function AiModeToggle({ value, onChange }: AiModeToggleProps): JSX.Element {
  return (
    <ToggleGroup
      label="AI mode"
      value={value}
      options={AI_MODE_OPTIONS}
      onChange={(next) => {
        const mode = toAiMode(next);
        if (mode !== undefined) {
          onChange(mode);
        }
      }}
    />
  );
}
import type { ToggleGroupOption } from '@/design-system';

// D15: the document is shown either as the Visual editor or as its raw Markdown source.
export const VIEW_MODES = ['visual', 'markdown'] as const;
export type ViewMode = (typeof VIEW_MODES)[number];

// D1: Ambient lets the co-author suggest on its own; On Demand waits for the user to ask.
// State only until the AI phases give each mode its behavior.
export const AI_MODES = ['ambient', 'on-demand'] as const;
export type AiMode = (typeof AI_MODES)[number];

export const VIEW_MODE_OPTIONS: readonly ToggleGroupOption[] = [
  { value: 'visual', label: 'Visual' },
  { value: 'markdown', label: 'Markdown' },
];

export const AI_MODE_OPTIONS: readonly ToggleGroupOption[] = [
  { value: 'ambient', label: 'Ambient' },
  { value: 'on-demand', label: 'On Demand' },
];

// Narrows a ToggleGroup value (a plain string) to a mode; undefined for anything unknown.
export function toViewMode(value: string): ViewMode | undefined {
  return VIEW_MODES.find((mode) => mode === value);
}

export function toAiMode(value: string): AiMode | undefined {
  return AI_MODES.find((mode) => mode === value);
}
