import type { JSX } from 'react';
import { Icon, type IconName } from '../../icons';
import { VisuallyHidden } from '../VisuallyHidden/VisuallyHidden';
import './ToggleGroup.css';

export interface ToggleGroupOption {
  value: string;
  label: string;
  icon?: IconName;
}

export interface ToggleGroupProps {
  // Accessible name of the group, for example "View".
  label: string;
  value: string;
  onChange: (value: string) => void;
  options: readonly ToggleGroupOption[];
  // Shows only the icon; the label stays in the accessible name (S7).
  iconOnly?: boolean;
}

// S4: a set of pressed-state buttons. Each option is a native button; Tab moves between them.
export function ToggleGroup({
  label,
  value,
  onChange,
  options,
  iconOnly = false,
}: ToggleGroupProps): JSX.Element {
  return (
    <div role="group" aria-label={label} className="ds-toggle-group">
      {options.map((option) => {
        const selected = option.value === value;
        return (
          <button
            key={option.value}
            type="button"
            aria-pressed={selected}
            className={
              selected
                ? 'ds-toggle-group__button ds-toggle-group__button--selected'
                : 'ds-toggle-group__button'
            }
            onClick={() => {
              onChange(option.value);
            }}
          >
            {option.icon !== undefined ? <Icon name={option.icon} /> : null}
            {iconOnly ? <VisuallyHidden>{option.label}</VisuallyHidden> : option.label}
          </button>
        );
      })}
    </div>
  );
}
import type { JSX } from 'react';
import { Icon, type IconName } from '../../icons';
import { type ButtonProps } from '../Button/Button';
import '../Button/Button.css';
import './IconButton.css';

export interface IconButtonProps extends Omit<ButtonProps, 'children' | 'aria-label'> {
  icon: IconName;
  // Required: an icon-only control has no visible text, so the label is its accessible name (S7).
  label: string;
}

// S4: icon-only button. The icon is decorative; the label carries the meaning.
export function IconButton({
  icon,
  label,
  variant = 'subtle',
  type = 'button',
  ...rest
}: IconButtonProps): JSX.Element {
  return (
    <button
      type={type}
      aria-label={label}
      className={`ds-button ds-button--${variant} ds-icon-button`}
      {...rest}
    >
      <Icon name={icon} />
    </button>
  );
}

