}
import type { JSX, ReactNode } from 'react';
import { Icon, Spinner, Tooltip, VisuallyHidden } from '@/design-system';
import type { AiStatus } from './aiStatus';
import { useAiStatus } from './AiStatusContext';
import { modelLines, useModelNames } from './useModelNames';
import './StatusIndicator.css';

// D14: neutral, factual one-liners (D8). Each state has its own icon, so colour is not the only
// cue (S7). The text is the tooltip and the live-region message; the bar shows only the icon.
const STATUS_LABELS: Record<AiStatus, string> = {
  ready: 'AI Ready',
  working: 'AI Is Working',
  unavailable: 'AI Unavailable. Retry Later',
  out_of_credit: 'AI Is Out of Credit',
};

// The spinner is its own status region, so its label is empty to avoid announcing twice.
const iconFor = (status: AiStatus): ReactNode => {
  switch (status) {
    case 'ready':
      return <Icon name="check" />;
    case 'working':
      return <Spinner label="" />;
    case 'unavailable':
    case 'out_of_credit':
      return <Icon name="x" />;
  }
};

export function StatusIndicator(): JSX.Element {
  const status = useAiStatus();
  const label = STATUS_LABELS[status];
  const models = useModelNames();
  return (
    <Tooltip content={models === null ? label : `${label}\n${modelLines(models)}`}>
      <span className={`ai-status ai-status--${status}`} tabIndex={0} role="status">
        <span className="ai-status__icon">{iconFor(status)}</span>
        <VisuallyHidden>{label}</VisuallyHidden>
      </span>
    </Tooltip>
  );
}
import type { JSX } from 'react';
import type { Editor } from '@tiptap/react';
import type { RewriteActions } from '../suggestion/rewriteActions';
import { SelectionToolbar } from './SelectionToolbar';
import { useSelectionBox } from './useSelectionBox';
import { useVisualViewport } from './useVisualViewport';

// D6 default for "Fix Tone": the AI is asked to fix the tone, and the tone picker stays on auto.
const FIX_TONE_INSTRUCTION = 'Fix the tone';

export interface SelectionActionsProps {
  editor: Editor | null;
  // False while a rewrite card is open or the raw Markdown view is shown (D15).
  enabled: boolean;
  actions: RewriteActions;
}

// D9: the selection toolbar wired to the rewrite actions. It shows only while text is selected,
// and it never takes focus from the editor.
export function SelectionActions({
  editor,
  enabled,
  actions,
}: SelectionActionsProps): JSX.Element | null {
  const box = useSelectionBox(editor, enabled);
  const viewport = useVisualViewport();
  return (
    <SelectionToolbar
      anchorRect={box}
      viewport={viewport}
      onRewrite={() => {
        actions.rewriteSelection({ type: 'setTone', tone: 'auto' });
      }}
      onFixTone={() => {
        actions.rewriteSelection({ type: 'addInstruction', text: FIX_TONE_INSTRUCTION });
      }}
      onShorten={() => {
        actions.rewriteSelection({ type: 'setLength', length: 'shorter' });
      }}
      onInstruction={(text) => {
        actions.rewriteSelection({ type: 'addInstruction', text });
      }}
      onDismiss={actions.collapseSelection}
    />
  );
}
import {
  useState,
  type SyntheticEvent,
  type JSX,
  type KeyboardEvent as ReactKeyboardEvent,
} from 'react';
import { Button, TextField } from '@/design-system';
import { keepEditorSelection } from './keepSelection';
import { toolbarPosition, type Box } from './toolbarPosition';
import './SelectionToolbar.css';

export interface SelectionToolbarProps {
  // The selection in client coordinates. Null hides the toolbar.
  anchorRect: Box | null;
  // The visual viewport (window.visualViewport) in the same coordinates.
  viewport: Box;
  onRewrite: () => void;
  onFixTone: () => void;
  onShorten: () => void;
  onInstruction: (text: string) => void;
  onDismiss: () => void;
}

// D9, S9: floating actions for a selected passage. It is not a Popover: a popover moves focus into
// itself on open, which would pull focus out of the editor on every selection. It is reached by
// Tab and dismissed with Esc.
export function SelectionToolbar({
  anchorRect,
  viewport,
  onRewrite,
  onFixTone,
  onShorten,
  onInstruction,
  onDismiss,
}: SelectionToolbarProps): JSX.Element | null {
  const [draft, setDraft] = useState('');
  if (anchorRect === null) {
    return null;
  }
  const { top, left } = toolbarPosition(anchorRect, viewport);
  const trimmed = draft.trim();

  function handleSubmit(event: SyntheticEvent<HTMLFormElement, SubmitEvent>): void {
    event.preventDefault();
    if (trimmed.length === 0) {
      return;
    }
    onInstruction(trimmed);
    setDraft('');
  }

  function handleKeyDown(event: ReactKeyboardEvent<HTMLDivElement>): void {
    if (event.key === 'Escape') {
      event.stopPropagation();
      onDismiss();
    }
  }

  return (
    <div
      role="group"
      aria-label="Selection actions"
      className="selection-toolbar"
      style={{ top, left }}
      onKeyDown={handleKeyDown}
      onMouseDown={keepEditorSelection}
    >
      <Button onClick={onRewrite}>Rewrite</Button>
      <Button onClick={onFixTone}>Fix Tone</Button>
      <Button onClick={onShorten}>Shorten</Button>
      <span className="selection-toolbar__divider" aria-hidden="true" />
      <form className="selection-toolbar__form" onSubmit={handleSubmit}>
        <div className="selection-toolbar__field">
          <TextField
            label="Instruction"
            hideLabel
            placeholder="Ask the AI to..."
            value={draft}
            onChange={(event) => {
              setDraft(event.target.value);
            }}
          />
        </div>
        <Button type="submit" disabled={trimmed.length === 0}>
          Apply
        </Button>
      </form>
    </div>
  );
}

