import type { ButtonHTMLAttributes, JSX } from 'react';
import './Button.css';

export type ButtonVariant = 'primary' | 'subtle' | 'danger';

export interface ButtonProps extends Omit<ButtonHTMLAttributes<HTMLButtonElement>, 'className'> {
  variant?: ButtonVariant;
}

// S4: custom button modelled on the ADS Button. Children are the label, a verb naming the outcome.
// Focus ring comes from the global :focus-visible rule (S7).
export function Button({
  variant = 'subtle',
  type = 'button',
  children,
  ...rest
}: ButtonProps): JSX.Element {
  return (
    <button type={type} className={`ds-button ds-button--${variant}`} {...rest}>
      {children}
    </button>
  );
}
/* S5, S9: a compact bubble over the selection (prototype .bub: 4px padding, 2px gap, 9px label
   padding, 10px radius). The dark bubble becomes the overlay surface so it follows the light and
   dark themes. Tokens only. */
.selection-toolbar {
  position: fixed;
  z-index: var(--app-z-drawer);
  display: flex;
  align-items: center;
  gap: var(--ds-space-025);
  box-sizing: border-box;
  inline-size: 560px;
  max-inline-size: calc(100vw - 2 * var(--ds-space-200));
  padding: var(--ds-space-050);
  border: var(--ds-border-width) solid var(--ds-border);
  border-radius: var(--ds-radius-xlarge);
  background: var(--ds-surface-overlay);
  color: var(--ds-text);
  box-shadow: var(--ds-shadow-overlay);
  font: var(--ds-font-body);
}

