/* H4 card: preview pane above the title and edit time, shadow on hover (S9: no hover-only
   controls; the card stays fully usable without it). */
.doc-card {
  display: flex;
  flex-direction: column;
  overflow: hidden;
  border: var(--ds-border-width) solid var(--ds-border);
  border-radius: var(--ds-radius-large);
  background: var(--ds-surface-raised);
  transition: box-shadow var(--ds-duration-medium);
}

.doc-card:hover {
  box-shadow: var(--ds-shadow-overlay);
}

.doc-card__preview {
  block-size: calc(var(--ds-space-100) * 18);
  padding: var(--ds-space-150) var(--ds-space-200);
  overflow: hidden;
  overflow-wrap: anywhere;
  border-block-end: var(--ds-border-width) solid var(--ds-border);
  background: var(--ds-surface-container);
  font: var(--ds-font-body-small);
  color: var(--ds-text-subtle);
}

.doc-card__body {
  display: flex;
  flex-direction: column;
  gap: var(--ds-space-025);
  padding: var(--ds-space-100) var(--ds-space-150);
  min-inline-size: 0;
}
