/* S2: tokens only. A 24px round bubble in the brand colour; effects use transform and opacity. */
.ds-ai-bubble {
  position: relative;
  display: inline-grid;
  place-items: center;
  box-sizing: border-box;
  inline-size: var(--ds-space-300);
  block-size: var(--ds-space-300);
  padding: 0;
