import { useEffect, useRef, useState, type JSX } from 'react';
import { EditorContent, useEditor, type Editor, type UseEditorOptions } from '@tiptap/react';
import { createCurrentBlockExtension } from './currentBlock/currentBlockExtension';
import { createEditorExtensions } from './markdown/extensions';
import { createFlagsPlugin } from './flags/flagsPlugin';
import { bindFlagOpener, createFlagNavigation } from './flagNavigation';
import { createSuggestionPlugin } from './suggestion/suggestionPlugin';
import { createRestructurePreviewExtension } from './restructure/restructurePreviewPlugin';
import { createSlashExtension } from './slash/slashExtension';
import { SlashMenu } from './slash/SlashMenu';
import { slashOptionDomId, type SlashItem } from './slash/slashItems';
import { useSlashMenu } from './slash/useSlashMenu';
import { AiBubbles } from './bubble/AiBubbles';
import { useParagraphBubbles } from './bubble/useParagraphBubbles';
import { HeadingActions } from './toolbar/HeadingActions';
import { useHeadingBoxes } from './toolbar/useHeadingBoxes';
import { useFlagAnalysis } from './useFlagAnalysis';
import { useFlags } from './useFlags';
import './flags/flags.css';
import './suggestion/suggestion.css';
import './EditorSurface.css';

export interface EditorSurfaceProps {
  // Stored Markdown, parsed once when the editor is created. The route keys the page by id,
  // so a new document always mounts a new surface.
  initialMarkdown: string;
  // Called with the canonical Markdown after every document change (T2: Markdown is the document;
  // D17: the caller autosaves it).
  onChange: (markdown: string) => void;
  // Called once per editor instance with the live editor (twice under StrictMode in dev, with the
  // same instance), so callers can drive it through its commands.
  onReady?: ((editor: Editor) => void) | undefined;
  // True while the AI must not analyze: On Demand (D1) or the raw Markdown view (D15).
  aiPaused: boolean;
  // Asked to open a flag's popover by keyboard or pointer (D17).
  onFlagOpen: (flagId: string) => void;
  // The slash menu item the author chose (D12).
  onSlashChoose: (item: SlashItem) => void;
  // "Improve Section" was pressed for the heading at this position (D9).
  onImprove: (headingPos: number) => void;
}

// T1, D13: TipTap owns the editing state; the document leaves it only as Markdown. The editor is
// created from Markdown with an explicit contentType, so stored text is never sniffed as HTML (T10).
// useEditor destroys the editor on unmount.
export function EditorSurface({
  initialMarkdown,
  onChange,
  onReady,
  aiPaused,
  onFlagOpen,
  onSlashChoose,
  onImprove,
}: EditorSurfaceProps): JSX.Element {
  // Refs keep the latest callbacks without recreating the editor on every render.
  const onChangeRef = useRef(onChange);
  const onReadyRef = useRef(onReady);
  const actionsRef = useRef({ onSlashChoose, onImprove });
  useEffect(() => {
    onChangeRef.current = onChange;
    onReadyRef.current = onReady;
    actionsRef.current = { onSlashChoose, onImprove };
  });

  // The menu's handlers are stable, so the extension built once below keeps working.
  const slash = useSlashMenu((item) => {
    actionsRef.current.onSlashChoose(item);
  });

  // Built once per mount. TipTap compares options on every render, so a new object or callback
  // each render would call setOptions on every title keystroke.
  const [options] = useState<UseEditorOptions>(() => ({
    extensions: [
      ...createEditorExtensions(),
      createFlagsPlugin(),
      createSuggestionPlugin(),
      createFlagNavigation(),
      createSlashExtension(slash.handlers),
      createRestructurePreviewExtension(),
      createCurrentBlockExtension(),
    ],
    contentType: 'markdown',
    content: initialMarkdown,
    editorProps: {
      attributes: {
        role: 'textbox',
        'aria-label': 'Document',
        'aria-multiline': 'true',
      },
    },
    onUpdate: ({ editor: current }) => {
      onChangeRef.current(current.getMarkdown());
    },
  }));
  const editor = useEditor(options);
  const analyzingHash = useFlagAnalysis(editor, aiPaused);
  const bubbles = useParagraphBubbles(editor, analyzingHash, useFlags(editor));
  const headings = useHeadingBoxes(editor);

  // The keyboard's active menu item is announced through the editor, which keeps focus (D12).
  const activeItem = slash.view === null ? undefined : slash.view.items[slash.view.activeIndex];
  const activeId = activeItem === undefined ? null : slashOptionDomId(activeItem.id);
  useEffect(() => {
    if (activeId === null) {
      editor.view.dom.removeAttribute('aria-activedescendant');
    } else {
      editor.view.dom.setAttribute('aria-activedescendant', activeId);
    }
  }, [editor, activeId]);

  // The extension reads its callback from editor storage; this effect keeps it current (D17).
  useEffect(() => {
    bindFlagOpener(editor, onFlagOpen);
  }, [editor, onFlagOpen]);

  useEffect(() => {
    onReadyRef.current?.(editor);
  }, [editor]);

  return (
    <div className="editor-surface-frame">
      <EditorContent editor={editor} className="editor-surface" />
      <HeadingActions
        boxes={headings}
        onImprove={(headingPos) => {
          actionsRef.current.onImprove(headingPos);
        }}
      />
      <AiBubbles bubbles={bubbles} onOpenFlag={onFlagOpen} />
      {slash.view === null ? null : (
        <SlashMenu
          items={slash.view.items}
          activeIndex={slash.view.activeIndex}
          position={slash.view.position}
          onSelect={slash.choose}
        />
      )}
    </div>
  );
}

import { useEffect, useState } from 'react';
import type { Editor } from '@tiptap/react';
import type { Transaction } from '@tiptap/pm/state';
import type { Flag } from '@shared/schemas';
import { hashOfText } from './analyze/paragraphContext';
import { useAnalyzeScheduler } from './analyze/useAnalyzeScheduler';
import { paragraphContextOf, paragraphIdAt, paragraphsOf } from './paragraphs';
import { setFlagsMeta } from './flags/flagsPlugin';

// Applies one paragraph's flags to the paragraph whose text still has this hash (T10). The text is
// looked up by hash, not by id, because inserting a paragraph above renumbers the ids.
// DEBT: with two identical paragraphs only the first gets flags; applying to both would leave a
// flag that Dismiss does not clear. Revisit with a per-paragraph flag identity.
function showParagraphFlags(editor: Editor, hash: string, flags: readonly Flag[]): void {
  const paragraph = paragraphsOf(editor.state.doc).find((entry) => hashOfText(entry.text) === hash);
  if (paragraph === undefined) {
    return;
  }
  editor.view.dispatch(
    setFlagsMeta(editor.state.tr, { paragraphPos: paragraph.pos, blockHash: hash, flags }),
  );
}

// Where the paragraph holding the caret starts, or undefined when the caret is in a heading.
function caretParagraphPos(editor: Editor): number | undefined {
  const paragraphs = paragraphsOf(editor.state.doc);
  const id = paragraphIdAt(paragraphs, editor.state.selection.$from);
  return paragraphs.find((paragraph) => paragraph.id === id)?.pos;
}

// D4: connects the editor to the analyze scheduler. Edits mark the caret paragraph and start its
// pause; a collapsed caret leaving a focused paragraph analyzes it. Range selections and blur send
// nothing. Nothing is sent while `paused` (D1 On Demand, D15 raw view).
export function useFlagAnalysis(editor: Editor, paused: boolean): string | null {
  // The hash of the paragraph being analyzed right now, for the AI bubble's loading state.
  const [analyzingHash, setAnalyzingHash] = useState<string | null>(null);
  const scheduler = useAnalyzeScheduler({
    paused,
    onWorking: setAnalyzingHash,
    onFlags: (hash, flags) => {
      showParagraphFlags(editor, hash, flags);
    },
    isLive: (hash) =>
      paragraphsOf(editor.state.doc).some((paragraph) => hashOfText(paragraph.text) === hash),
  });

  useEffect(() => {
    if (paused) {
      scheduler.pause();
    }
  }, [paused, scheduler]);

  useEffect(() => {
    // The start position of the paragraph the caret was last in. Every transaction maps it, so a
    // paragraph inserted above (Enter) keeps pointing at the same paragraph.
    let caretPos = caretParagraphPos(editor);
    const handleTransaction = ({ transaction }: { transaction: Transaction }): void => {
      if (!transaction.docChanged && !transaction.selectionSet) {
        return;
      }
      caretPos = caretPos === undefined ? undefined : transaction.mapping.map(caretPos);
      const { selection } = editor.state;
      const paragraphs = paragraphsOf(editor.state.doc);
      const currentId = paragraphIdAt(paragraphs, selection.$from);
      if (selection.empty) {
        const previous = paragraphs.find((paragraph) => paragraph.pos === caretPos);
        // Only a collapsed caret in a focused editor counts as leaving (D4).
        if (editor.isFocused && previous !== undefined && previous.id !== currentId) {
          const left = paragraphContextOf(paragraphs, previous.id);
          if (left !== undefined) {
            scheduler.paragraphLeft(left);
          }
        }
        const current = paragraphs.find((paragraph) => paragraph.id === currentId);
        caretPos = current?.pos;
      }
      if (transaction.docChanged && currentId !== undefined) {
        const edited = paragraphContextOf(paragraphs, currentId);
        if (edited !== undefined) {
          scheduler.paragraphEdited(edited);
        }
      }
    };
    editor.on('transaction', handleTransaction);
    return () => {
      editor.off('transaction', handleTransaction);
    };
  }, [editor, scheduler]);

  return analyzingHash;
}

import type { AiClientResult, AiRequestOf } from '@/features/ai';
import type { Flag } from '@shared/schemas';
import { DEFAULT_IDLE_PAUSE_SECONDS } from './idlePause';
import { createLruCache, type LruCache } from './lruCache';
import {
  hashOfText,
  isAnalyzable,
  toAnalyzeRequest,
  type ParagraphContext,
} from './paragraphContext';

// D4: analyze after the typing pause, so nothing fires mid-typing. Read from settings by the hook.
export const DEFAULT_PAUSE_MS = DEFAULT_IDLE_PAUSE_SECONDS * 1000;
// Bounded so a long session cannot grow the caches without limit (AGENTS: bound everything).
export const ANALYZE_CACHE_CAPACITY = 200;
// D14: the first outage waits 30 s; each further consecutive failure doubles the wait, up to 5 min.
export const BASE_COOLDOWN_MS = 30_000;
export const MAX_COOLDOWN_MS = 300_000;
// Paragraphs left while a call is in flight. Only the newest few are kept; older ones are dropped.
export const QUEUE_CAPACITY = 3;
// After an outage the same text is retried when the wait ends, at most this many times in a row;
// after that only a new edit or caret leave tries again, so a long outage costs a bounded few calls.
export const MAX_AUTO_RETRIES = 3;

export interface AnalyzeClient {
  run: (
    request: AiRequestOf<'analyze'>,
    signal?: AbortSignal,
  ) => Promise<AiClientResult<'analyze'>>;
}

// Method shorthand keeps the browser's own timer functions assignable to this interface.
export interface SchedulerTimers {
  setTimeout(callback: () => void, delay_ms: number): unknown;
  clearTimeout(handle: unknown): void;
}

export interface AnalyzeSchedulerDeps {
  client: AnalyzeClient;
  timers: SchedulerTimers;
  // Injected clock: the cooldown is measured with it (AGENTS: inject the clock).
  now: () => number;
  // A hidden tab holds calls back; nobody is looking at the flags.
  isHidden: () => boolean;
  // On Demand mode, the raw view and out of credit hold calls back (D1, D14, D15).
  isPaused: () => boolean;
  // True while a paragraph with this text hash is still in the document (T10).
  isLive: (hash: string) => boolean;
  onFlags: (hash: string, flags: Flag[]) => void;
  // The text hash of the paragraph being analyzed, or null when no call is in flight. Drives the
  // AI bubble's loading state; it never carries the text itself.
  onWorking?: (hash: string | null) => void;
  pause_ms?: number;
}

export interface AnalyzeScheduler {
  // Every edit to the caret paragraph: restarts the pause timer and marks the text as edited.
  paragraphEdited: (ctx: ParagraphContext) => void;
  // The collapsed caret left the paragraph: analyzes it at once if it was edited since its last attempt.
  paragraphLeft: (ctx: ParagraphContext) => void;
  // Clears the pause timer and the queue. A call already in flight is left to finish.
  pause: () => void;
  // Unmount: aborts the call in flight and ignores everything after.
  dispose: () => void;
}

// Waits between outages: 30 s, 60 s, 120 s, ... capped at 5 min (D14).
const cooldownAfter = (failures: number): number =>
  Math.min(BASE_COOLDOWN_MS * 2 ** (failures - 1), MAX_COOLDOWN_MS);

// Ambient analysis call policy (D1, D4, D14, T10). Calls go out only for text the user edited since
// it was last attempted; text is cached by its own hash; one call is in flight at a time.
export const createAnalyzeScheduler = (deps: AnalyzeSchedulerDeps): AnalyzeScheduler => {
  const { client, timers, now, isHidden, isPaused, isLive, onFlags } = deps;
  const pause_ms = deps.pause_ms ?? DEFAULT_PAUSE_MS;
  // Successful results by text hash. The same text is never sent twice.
  const cache: LruCache<Flag[]> = createLruCache<Flag[]>(ANALYZE_CACHE_CAPACITY);
  // Text hashes edited since their last attempt. Leaving or pausing only sends edited text.
  const edited: LruCache<true> = createLruCache<true>(ANALYZE_CACHE_CAPACITY);
  // Paragraphs waiting for the call in flight, oldest first, one per text hash.
  const queue: ParagraphContext[] = [];
  let idle: { readonly handle: unknown } | undefined;
  // The one timer that retries held-back or failed text when the cooldown ends.
  let wake: { readonly handle: unknown } | undefined;
  let inFlight: AbortController | undefined;
  let failures = 0;
  let cooldownEnds_ms = 0;
  let disposed = false;

  const clearIdle = (): void => {
    if (idle === undefined) {
      return;
    }
    timers.clearTimeout(idle.handle);
    idle = undefined;
  };

  const clearWake = (): void => {
    if (wake === undefined) {
      return;
    }
    timers.clearTimeout(wake.handle);
    wake = undefined;
  };

  const inCooldown = (): boolean => now() < cooldownEnds_ms;

  // Copies the flags so a listener cannot mutate the cached array.
  const emitIfLive = (hash: string, flags: readonly Flag[]): void => {
    if (isLive(hash)) {
      onFlags(hash, [...flags]);
    }
  };

  // Retries one paragraph when the cooldown ends, if its text is still owed an attempt.
  function scheduleWake(ctx: ParagraphContext): void {
    clearWake();
    const hash = hashOfText(ctx.text);
    const handle = timers.setTimeout(
      () => {
        wake = undefined;
        if (edited.has(hash)) {
          request(ctx);
        }
      },
      Math.max(cooldownEnds_ms - now(), 0),
    );
    wake = { handle };
  }

  const enqueue = (ctx: ParagraphContext): void => {
    const hash = hashOfText(ctx.text);
    const index = queue.findIndex((queued) => hashOfText(queued.text) === hash);
    if (index !== -1) {
      queue.splice(index, 1);
    }
    queue.push(ctx);
    if (queue.length > QUEUE_CAPACITY) {
      queue.shift();
    }
  };

  const record = (ctx: ParagraphContext, result: AiClientResult<'analyze'>): void => {
    const hash = hashOfText(ctx.text);
    if (result.ok) {
      failures = 0;
      cooldownEnds_ms = 0;
      cache.set(hash, result.value.flags);
      // A call that was already in flight is let finish, but its flags are not shown once analysis
      // is paused (On Demand or the raw view, D1, D15); the cache keeps them for later.
      if (!isPaused()) {
        emitIfLive(hash, result.value.flags);
      }
      return;
    }
    // Out of credit is handled by the status, which pauses analysis (D14).
    if (result.error.kind === 'out_of_credit') {
      return;
    }
    failures += 1;
    cooldownEnds_ms = now() + cooldownAfter(failures);
    // The text was not analyzed, so it is still owed an attempt: when the wait ends it is sent again
    // (bounded by MAX_AUTO_RETRIES), so a short outage does not leave Ambient silent until the next edit.
    edited.set(hash, true);
    if (failures <= MAX_AUTO_RETRIES) {
      scheduleWake(ctx);
    }
  };

  // The next queued paragraph to send, or undefined. Held-back work is dropped, and its text stays
  // edited. One wake slot exists, so the latest held paragraph is retried when the cooldown ends and the
  // others wait for a new trigger (bounded by MAX_AUTO_RETRIES, D14).
  const nextToSend = (): ParagraphContext | undefined => {
    for (let next = queue.shift(); next !== undefined; next = queue.shift()) {
      if (disposed || isPaused() || isHidden()) {
        queue.length = 0;
        return undefined;
      }
      if (inCooldown()) {
        queue.length = 0;
        scheduleWake(next);
        return undefined;
      }
      const hash = hashOfText(next.text);
      const cached = cache.get(hash);
      if (cached === undefined) {
        return next;
      }
      edited.delete(hash);
      emitIfLive(hash, cached);
    }
    return undefined;
  };

  // Sends one paragraph and then the queue, one call at a time. Only the call in flight is aborted
  // by dispose; edits and pauses never abort it.
  const callAndQueue = async (first: ParagraphContext): Promise<void> => {
    let ctx: ParagraphContext | undefined = first;
    while (ctx !== undefined) {
      const hash = hashOfText(ctx.text);
      const controller = new AbortController();
      inFlight = controller;
      edited.delete(hash);
      deps.onWorking?.(hash);
      const result = await client.run(toAnalyzeRequest(ctx), controller.signal);
      inFlight = undefined;
      deps.onWorking?.(null);
      if (disposed) {
        return;
      }
      record(ctx, result);
      ctx = nextToSend();
    }
  };

  // A trigger for one paragraph: answer from cache, queue behind the call in flight, or send.
  const request = (ctx: ParagraphContext): void => {
    if (disposed || !isAnalyzable(ctx) || isPaused() || isHidden()) {
      return;
    }
    const hash = hashOfText(ctx.text);
    const cached = cache.get(hash);
    if (cached !== undefined) {
      edited.delete(hash);
      emitIfLive(hash, cached);
      return;
    }
    if (inFlight !== undefined) {
      enqueue(ctx);
      return;
    }
    if (inCooldown()) {
      scheduleWake(ctx);
      return;
    }
    void callAndQueue(ctx);
  };

  const paragraphEdited = (ctx: ParagraphContext): void => {
    if (disposed) {
      return;
    }
    clearIdle();
    const hash = hashOfText(ctx.text);
    edited.set(hash, true);
    if (!isAnalyzable(ctx)) {
      return;
    }
    const handle = timers.setTimeout(() => {
      idle = undefined;
      if (edited.has(hash)) {
        request(ctx);
      }
    }, pause_ms);
    idle = { handle };
  };

  const paragraphLeft = (ctx: ParagraphContext): void => {
    if (disposed) {
      return;
    }
    clearIdle();
    if (edited.has(hashOfText(ctx.text))) {
      request(ctx);
    }
  };

  const pause = (): void => {
    clearIdle();
    clearWake();
    queue.length = 0;
  };

  const dispose = (): void => {
    pause();
    inFlight?.abort();
    inFlight = undefined;
    disposed = true;
  };

  return { paragraphEdited, paragraphLeft, pause, dispose };
};

/* Tokens only (S2). Document text is at least 1rem; the page column keeps a 45-75ch measure. */
.editor-page {
  display: flex;
  flex-direction: column;
  min-block-size: 100dvh;
  box-sizing: border-box;
}

/* A slim bar: 8px above and below, 16px at the sides, controls in one row that wraps at 360px. */
.editor-top-bar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--ds-space-100);
  padding-inline: var(--ds-space-200);
  padding-block: var(--ds-space-100);
  min-inline-size: 0;
}

/* Every control in the bar is 32px tall and centred on one line, so icons and the title align. */
.editor-top-bar > *,
.editor-top-bar__toggles > * {
  min-block-size: 32px;
}

.editor-top-bar__ai,
.editor-top-bar__flags {
  align-items: center;
}

.editor-top-bar .ds-icon-link {
  border-radius: var(--ds-radius-full);
}

/* Below md the title takes its own full row beside the back arrow and overflow menu (S9). */
.editor-top-bar__overflow {
  margin-inline-start: auto;
}

.editor-top-bar__title {
  flex: 1 1 100%;
  min-inline-size: 0;
}

/* The title always shows its box, so it reads as an input without pointing at it. */
.editor-top-bar__title .ds-text-field__input {
  box-sizing: border-box;
  inline-size: 100%;
  min-block-size: 32px;
  padding: 0 var(--ds-space-100);
  border: var(--ds-border-width) solid var(--ds-border-input);
  border-radius: var(--ds-radius-large);
  background: var(--ds-surface);
  color: var(--ds-text);
  font: var(--ds-font-body);
  font-weight: var(--ds-font-weight-medium);
}

.editor-top-bar__title .ds-text-field__input:hover {
  border-color: var(--ds-border-brand);
}

.editor-top-bar__title .ds-text-field__input:focus {
  outline: var(--ds-border-width-focused) solid var(--ds-border-focused);
  outline-offset: 0;
  border-color: transparent;
}

/* From md the title keeps a fixed width and the toggles, AI status and flag control sit to its
   right. 768px mirrors BREAKPOINTS.md (S9). */
@media (min-width: 768px) {
  .editor-top-bar__title {
    flex: 0 1 10rem;
  }
}

@media (min-width: 1024px) {
  .editor-top-bar__title {
    flex: 0 1 15rem;
  }
}

/* The view and AI toggles are pushed to the right edge, in one row with the other controls. */
.editor-top-bar__toggles {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--ds-space-100);
}

.editor-top-bar__flags {
  display: flex;
  justify-content: flex-end;
}

.editor-top-bar__ai {
  display: flex;
  justify-content: flex-start;
}

/* From md the controls sit at the right edge and keep reserved widths, so they can come and go
   without moving what sits beside them. Below md they wrap flush left, as one tidy block. */
@media (min-width: 768px) {
  .editor-top-bar__flags {
    margin-inline-start: auto;
  }
}

/* The reserved widths need room: below lg they would push the status chip onto its own row. */
@media (min-width: 1024px) {
  .editor-top-bar__flags {
    min-inline-size: 7.5rem;
  }
}

/* The page column: centred at the prototype's 740px, with generous top space (56px) and 80px at the
   bottom. The 16px side gutter holds at phone width; from md the column gets the 24px side space. */
.editor-page-main {
  display: flex;
  flex: 1 0 auto;
  flex-direction: column;
  gap: var(--ds-space-100);
  inline-size: 100%;
  max-inline-size: 46.25rem;
  margin-inline: auto;
  padding-inline: var(--ds-space-200);
  padding-block: calc(var(--ds-space-600) + var(--ds-space-100)) var(--ds-space-1000);
  min-inline-size: 0;
  box-sizing: border-box;
}

@media (min-width: 768px) {
  .editor-page-main {
    padding-inline: var(--ds-space-300);
  }
}

/* The editing body fills the viewport below the bar (the hidden raw view keeps the same box). */
.editor-page-body {
  display: flex;
  flex: 1 0 auto;
  flex-direction: column;
  min-block-size: 0;
}

/* The author's display rule must not override the hidden attribute on the raw-view switch. */
.editor-page-body[hidden] {
  display: none;
}

@media (pointer: coarse) {
  .editor-top-bar .ds-icon-link,
  .editor-top-bar .ds-button,
  .editor-top-bar__name {
    min-block-size: 44px;
    min-inline-size: 44px;
    display: inline-flex;
    align-items: center;
  }
}

/* The raw Markdown view uses the room: a wider column than the reading page (D15). */
.editor-page-main--wide {
  max-inline-size: 64rem;
}

/* The wide layout uses the full page: the column and the text surface lose their reading caps. */
.editor-page-main--full {
  max-inline-size: none;
  /* Full width still keeps a clear gutter on both sides. */
  padding-inline: var(--ds-space-300);
}

@media (min-width: 768px) {
  .editor-page-main--full {
    padding-inline: var(--ds-space-400);
  }
}

.editor-page-main--full .editor-surface,
.editor-page-main--full .editor-surface-frame {
  max-inline-size: none;
}

tools.description:
Open the Browser pane: pass `url` to open a browser tab at a URL (no dev server needed — use this for external sites, staging, docs, or your deployed app), OR pass `name` to start a dev server from .claude/launch.json.

Start a dev server by name from .claude/launch.json. If .claude/launch.json doesn't exist, create it first with this format:
{
  "version": "0.0.1",
  "configurations": [
    {
      "name": "<unique-name>",
      "runtimeExecutable": "<command>",
      "runtimeArgs": ["<args>"],
      "port": <port>
    }
  ]
}
Set "runtimeExecutable" to the command (e.g. "npm"), "runtimeArgs" to the arguments (e.g. ["run", "dev"]), and "port" to the server port. An optional "url" (http/https) opens the preview there instead of http://localhost:<port>. A localhost "url" must be just the server's origin — no path or query, matching the entry's port — for example "https://localhost:8443" or "http://app.localhost:3000"; to show a specific page, navigate after the preview opens. Non-localhost URLs may carry paths and are subject to the user's permission and the organization's browsing policy. A configuration with "url" and no command attaches to an already-running server. Only include servers you actually need to preview. Reuses the server if already running. ALWAYS use this instead of Bash for running servers. If the deliverable is already published as an Artifact, update the Artifact instead of starting a server to show it.

