/* Tokens only (S2). Body text is at least 1rem and the measure stays within 75ch (AGENTS). The
   surface is a clean page: no box or border around the text (prototype .page). */
.editor-surface {
  display: flex;
  flex: 1 0 auto;
  flex-direction: column;
  min-block-size: 0;
  min-inline-size: 0;
  max-inline-size: 75ch;
  inline-size: 100%;
}

.editor-surface .ProseMirror {
  display: block;
  /* Fills the rest of the viewport below the bar; the document grows past this height. */
  flex: 1 0 auto;
  min-block-size: 60dvh;
  box-sizing: border-box;
  padding: 0;
  border: 0;
  border-radius: 0;
  background: transparent;
  color: var(--ds-text);
  /* Document text is 16px (AGENTS UI/UX); the body token is 14px, so the large body token is used.
     The reading line height (1.75) is set after the shorthand, which would otherwise reset it. */
  font: var(--ds-font-body-large);
  line-height: 1.75;
  overflow-wrap: anywhere;
}

/* Paragraphs keep the inline end free for the AI bubble (AiBubbles), so it never covers text. */
.editor-surface .ProseMirror p {
  padding-inline-end: var(--ds-space-500);
}

.editor-surface .ProseMirror > * + * {
  margin-block-start: var(--ds-space-100);
}

/* Headings keep clear of the "Improve section" control at the inline end (HeadingActions), so the
   control never sits over the heading text. The reserved width is two tokens: 80px plus 48px. */
.editor-surface .ProseMirror h1,
.editor-surface .ProseMirror h2,
.editor-surface .ProseMirror h3 {
  padding-inline-end: calc(var(--ds-space-1000) + var(--ds-space-600));
}

.editor-surface .ProseMirror h1 {
  font: var(--app-type-page-title);
}

/* The document's first block reads as its title (prototype h1.dt): large, bold, tight tracking. */
.editor-surface .ProseMirror > h1:first-child {
  font: var(--ds-font-heading-xxlarge);
  letter-spacing: -0.02em;
  margin-block-end: var(--ds-space-200);
}

.editor-surface .ProseMirror h2 {
  font: var(--app-type-section);
}

.editor-surface .ProseMirror h3 {
  font: var(--app-type-subsection);
}

/* Headings open a section: more space above than below, so each one groups the text after it. */
.editor-surface .ProseMirror > h1:not(:first-child),
.editor-surface .ProseMirror > h2,
.editor-surface .ProseMirror > h3 {
  margin-block-start: var(--ds-space-300);
  margin-block-end: var(--ds-space-050);
}

.editor-surface .ProseMirror blockquote {
  margin-inline: 0;
  padding-inline-start: var(--ds-space-200);
  border-inline-start: var(--ds-space-050) solid var(--ds-border-brand);
  color: var(--ds-text-subtle);
}

/* Highlighted text (prototype mark) uses the accent tint, not the browser's yellow. */
.editor-surface .ProseMirror mark {
  background-color: var(--ds-background-accent-purple-subtler);
  color: inherit;
  border-radius: var(--ds-radius-small);
}

.editor-surface .ProseMirror ul,
.editor-surface .ProseMirror ol {
  padding-inline-start: var(--ds-space-300);
}

.editor-surface .ProseMirror code {
  font: var(--ds-font-code);
}

.editor-surface .ProseMirror pre {
  padding: var(--ds-space-100);
  border-radius: var(--ds-radius-small);
  background: var(--ds-background-neutral);
  overflow-x: auto;
}

/* Placeholder from the Placeholder extension: shown only while the document is empty. */
.editor-surface .ProseMirror p.is-editor-empty:first-child::before {
  content: attr(data-placeholder);
  float: inline-start;
  block-size: 0;
  color: var(--ds-text-subtle);
  pointer-events: none;
}

/* The frame holds the editor and its floating controls (heading actions), positioned against it. */
.editor-surface-frame {
  position: relative;
  display: flex;
  flex: 1 0 auto;
  flex-direction: column;
  min-block-size: 0;
  min-inline-size: 0;
  max-inline-size: 75ch;
  inline-size: 100%;
}

/* The document is a clean page (prototype .ph): no outline in any focus state. The caret and the
   selection show where the author is writing (S7). */
.editor-surface .ProseMirror,
.editor-surface .ProseMirror:focus,
.editor-surface .ProseMirror:focus-visible {
  outline: none;
}

/* A selection stays readable in both themes: an accent tint with the normal text colour. */
.editor-surface .ProseMirror ::selection {
  background: var(--ds-background-accent-purple-subtler);
  color: var(--ds-text);
}

/* D17: a quiet marker in the margin beside the line being written (like Notion's block marker).
   It shows only while the editor has focus, and it is a bar, so it does not depend on colour. */
.editor-surface .ProseMirror .current-block {
  position: relative;
}

.editor-surface .ProseMirror.ProseMirror-focused .current-block::before {
  content: '';
  position: absolute;
  inset-block: 0.35em;
  inset-inline-start: calc(-1 * var(--ds-space-150));
  inline-size: var(--ds-space-025);
  border-radius: var(--ds-radius-full);
  background: var(--ds-border-bold);
}

