import type { JSX, MouseEvent } from 'react';
import { Icon, type IconName } from '../../icons';
import { useShell } from '../AppShell/AppShell';
import { Lozenge } from '../Lozenge/Lozenge';
import { VisuallyHidden } from '../VisuallyHidden/VisuallyHidden';
import './NavItem.css';

export interface NavItemProps {
  icon: IconName;
  label: string;
  // Renders a link. Without href the item is an action button that calls onClick.
  href?: string;
  // Called on activation. On a link the consumer may call event.preventDefault() to handle the
  // navigation itself (for example an in-app router); the real href stays for other clicks.
  onClick?: (event: MouseEvent<HTMLElement>) => void;
  // Marks the page the user is on: aria-current on a link plus a visible indicator bar (S7).
  current?: boolean;
  // Disabled items are announced but not actionable (H2, H3).
  disabled?: boolean;
  // Adds a "Soon" label to a disabled item (H2, H3).
  soon?: boolean;
  // Icon-rail state. Defaults to the enclosing AppShell's state.
  collapsed?: boolean;
}

function joinClassNames(parts: readonly (string | false | undefined)[]): string {
  return parts.filter((part): part is string => typeof part === 'string').join(' ');
}

// S4, S7, S9: one sidebar entry. The accessible name is always the label, even when the icon rail
// hides it visually. Choosing a link or action closes the drawer when the shell uses one.
export function NavItem({
  icon,
  label,
  href,
  onClick,
  current = false,
  disabled = false,
  soon = false,
  collapsed,
}: NavItemProps): JSX.Element {
  const shell = useShell();
  const isCollapsed = collapsed ?? shell.collapsed;
  const showSoon = disabled && soon;
  const className = joinClassNames([
    'ds-nav-item',
    current && 'ds-nav-item--current',
    disabled && 'ds-nav-item--disabled',
    isCollapsed && 'ds-nav-item--collapsed',
  ]);
  // With the icon rail the Soon label is hidden, so the spoken name carries it instead (H3).
  const hiddenLabel = showSoon ? `${label}, coming soon` : label;

  const body = (
    <>
      <Icon name={icon} />
      {isCollapsed ? (
        <VisuallyHidden>{hiddenLabel}</VisuallyHidden>
      ) : (
        <span className="ds-nav-item__label">{label}</span>
      )}
      {showSoon && !isCollapsed ? <Lozenge tone="soon">Soon</Lozenge> : null}
    </>
  );

  // Announced as unavailable; no onClick is attached, so activation does nothing.
  if (disabled) {
    return (
      <button type="button" className={className} aria-disabled="true">
        {body}
      </button>
    );
  }

  function activate(event: MouseEvent<HTMLElement>): void {
    onClick?.(event);
    shell.closeDrawer();
  }

  if (href !== undefined) {
    return (
      <a
        href={href}
        className={className}
        aria-current={current ? 'page' : undefined}
        onClick={activate}
      >
        {body}
      </a>
    );
  }

  return (
    <button type="button" className={className} onClick={activate}>
      {body}
    </button>
  );
}
import type { JSX, MouseEvent } from 'react';
import { useNavigate } from 'react-router';
import { Button, Icon, NavItem, useShell } from '@/design-system';

export interface HomeSidebarProps {
  onNewDocument: () => void;
}

const PRIMARY_BUTTON = 0;

// Only a plain left click is handled in-app. Middle clicks and modifier clicks keep the real href,
// so the browser can open the home screen in a new tab.
function isPlainPrimaryClick(event: MouseEvent<HTMLElement>): boolean {
  return (
    event.button === PRIMARY_BUTTON &&
    !event.metaKey &&
    !event.ctrlKey &&
    !event.shiftKey &&
    !event.altKey
  );
}

// H2: only New Document and the current Documents entry work. The rest are visible promises (Soon).
export function HomeSidebar({ onNewDocument }: HomeSidebarProps): JSX.Element {
  const navigate = useNavigate();
  const shell = useShell();

  // The primary action is a button, not a nav item, so it closes the drawer itself (S9).
  function startNewDocument(): void {
    shell.closeDrawer();
    onNewDocument();
  }

  // Stays in the single-page app: a plain click navigates with the router, not a full reload.
  function goHome(event: MouseEvent<HTMLElement>): void {
    if (!isPlainPrimaryClick(event)) {
      return;
    }
    event.preventDefault();
    void navigate('/');
  }

  return (
    <div className="home-sidebar">
      <div className="home-sidebar__new">
        <Button variant="primary" aria-label="New Document" onClick={startNewDocument}>
          <Icon name="plus" />
          <span className="home-sidebar__label">New Document</span>
        </Button>
      </div>
      <NavItem icon="file-text" label="Documents" href="/" current onClick={goHome} />
      <NavItem icon="pin" label="Pinned" disabled soon />
      <NavItem icon="users" label="Collaborations" disabled soon />
      <NavItem icon="archive" label="Archive" disabled soon />
    </div>
  );
}
