import type { JSX } from 'react';
import { Link } from 'react-router';
import { Avatar, Icon, TextField, ThemeSwitcher } from '@/design-system';

const PRODUCT_NAME = 'WebApp';
// The mark shows the first letter of the product name, so the two never drift apart.
const MARK_LETTER = PRODUCT_NAME.charAt(0);
const SEARCH_PLACEHOLDER = 'Search documents';
// H3: the disabled search explains itself on hover (the native disabled field cannot take focus).
const SEARCH_UNAVAILABLE = 'Search is coming later';

// H3: product name, a visible but disabled search with a "Soon" label, and a placeholder user.
export function HomeNavbar(): JSX.Element {
  return (
    <div className="home-navbar">
      <Link to="/" className="home-navbar__name">
        <span className="home-navbar__mark" aria-hidden="true">
          {MARK_LETTER}
        </span>
        {PRODUCT_NAME}
      </Link>
      <div className="home-navbar__search" title={SEARCH_UNAVAILABLE}>
        <div className="home-navbar__field">
          <span className="home-navbar__search-icon">
            <Icon name="search" size={16} />
          </span>
          <TextField
            label={SEARCH_PLACEHOLDER}
            hideLabel
            type="search"
            disabled
            aria-disabled="true"
            placeholder={SEARCH_PLACEHOLDER}
          />
        </div>
      </div>
      <div className="home-navbar__user">
        <ThemeSwitcher />
        <Avatar name="You" />
      </div>
    </div>
  );
}
/* S2: tokens only. The bubble hangs below its anchor and appears on hover or focus-within. */
.ds-tooltip {
  position: relative;
  display: inline-flex;
}

.ds-tooltip__anchor {
  display: inline-flex;
}

.ds-tooltip__bubble {
  position: absolute;
  inset-block-start: calc(100% + var(--ds-space-050));
  inset-inline-end: 0;
  z-index: var(--app-z-drawer);
  padding: var(--ds-space-050) var(--ds-space-100);
  border-radius: var(--ds-radius-large);
  background: var(--ds-background-neutral-bold);
  color: var(--ds-text-inverse);
  font: var(--ds-font-body-small);
  white-space: pre-line;
  min-inline-size: max-content;
  pointer-events: none;
  visibility: hidden;
  opacity: 0;
  transition: opacity var(--ds-duration-short) var(--ds-easing-out-practical);
}

.ds-tooltip--start .ds-tooltip__bubble {
  inset-inline-start: 0;
  inset-inline-end: auto;
}

.ds-tooltip:hover .ds-tooltip__bubble,
.ds-tooltip:focus-within .ds-tooltip__bubble {
  visibility: visible;
  opacity: 1;
}

@media (prefers-reduced-motion: reduce) {
  .ds-tooltip__bubble {
    transition: none;
  }
}
