                  type="button"
                  aria-label={control.label}
                  aria-pressed={pressed}
                  disabled={enabled[position] !== true}
                  tabIndex={position === tabStop ? 0 : -1}
                  className="formatting-toolbar__button"
                  onFocus={() => {
                    setFocusIndex(position);
                  }}
