import type { JSX } from 'react';
import { AiBubble } from '@/design-system';
import type { ParagraphBubble } from './useParagraphBubbles';
import './AiBubbles.css';

export interface AiBubblesProps {
  bubbles: readonly ParagraphBubble[];
  // Opens the suggestion card of the flag with this id (D5).
  onOpenFlag: (flagId: string) => void;
}

// S5: the AI bubbles in the frame's inline-end gutter, one per paragraph that is being analyzed or
// has suggestions. They sit over the reserved paragraph padding, so they never change the layout.
export function AiBubbles({ bubbles, onOpenFlag }: AiBubblesProps): JSX.Element {
  return (
    <div className="ai-bubbles">
      {bubbles.map((bubble) => (
        <div key={bubble.pos} className="ai-bubbles__item" style={{ top: bubble.top }}>
          {bubble.state === 'loading' || bubble.firstFlagId === undefined ? (
            <AiBubble state="loading" />
          ) : (
            <AiBubble
              state="ready"
              count={bubble.count}
              onOpen={() => {
                if (bubble.firstFlagId !== undefined) {
                  onOpenFlag(bubble.firstFlagId);
                }
              }}
            />
          )}
        </div>
      ))}
    </div>
  );
}
/* The layer covers the frame without catching clicks; only the bubbles take them. The first text
   line is 28px tall and the bubble 24px, so a 2px offset centres it on that line. */
.ai-bubbles {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.ai-bubbles__item {
  position: absolute;
  inset-inline-end: 0;
  margin-block-start: var(--ds-space-025);
  pointer-events: auto;
}
import type { JSX } from 'react';
import { Button } from '@/design-system';
import './ImproveSectionButton.css';

export interface ImproveSectionButtonProps {
  onImprove: () => void;
}

// D9, S9: a heading affordance that is always shown on touch screens and is reached by keyboard
// and focus on desktop, so it never depends on hover alone.
export function ImproveSectionButton({ onImprove }: ImproveSectionButtonProps): JSX.Element {
  return (
    <span className="improve-section">
      <Button onClick={onImprove}>Improve Section</Button>
    </span>
  );
}
/* S2: tokens only. A 24px round bubble in the brand colour; effects use transform and opacity. */
