pats={
 'openrouter key pattern':r'sk-or-[A-Za-z0-9_\-]{10,}',
 'generic sk- key':r'\bsk-[A-Za-z0-9_\-]{20,}',
 'bearer token':r'Bearer\s+[A-Za-z0-9._\-]{20,}',
